'use strict';
/* Guide — partie FR-1 : types de narrateur, notions de voix et de point de vue, Figures de style et Procédés de style.
   Chaque fiche : n nom · a autres noms · d description · u comment s’en servir · c attention · x exemples · t dans l’outil · s voir aussi (noms exacts).
   Les exemples sans auteur sont des phrases inventées pour illustrer le procédé. Les citations d’œuvres sont brèves.
   Norme de France ; les variantes de Belgique, de Suisse et du Québec sont signalées quand elles comptent. */

NARRATORS.push(
  { key:'primeira-protagonista', name:'Première personne — protagoniste',
    desc:'L’histoire est racontée par celui ou celle qui la vit (« je »). Le lecteur ne sait que ce que le héros sait, ressent et choisit de révéler. Genette parle de narrateur autodiégétique.',
    forces:'Intimité et voix forte ; identification immédiate ; idéal pour les arcs de transformation intérieure et les récits de mémoire.',
    risks:'Champ de vision limité ; difficile de montrer ce qui se passe en son absence ; la voix doit tenir tout le livre ; tentation de l’autoportrait complaisant.',
    examples:'*L’Étranger* (Albert Camus), *La Promesse de l’aube* (Romain Gary), *Voyage au bout de la nuit* (Louis-Ferdinand Céline), *L’Attrape-cœurs* (J. D. Salinger), *Les Grandes Espérances* (Charles Dickens).' },
  { key:'primeira-testemunha', name:'Première personne — témoin',
    desc:'Un « je » qui observe et rapporte l’histoire d’un autre personnage, plus central que lui. Genette parle de narrateur homodiégétique.',
    forces:'Préserve le mystère autour du héros ; permet l’admiration, le doute ou l’ironie de l’observateur ; le témoin peut changer à son tour.',
    risks:'Le narrateur peut devenir passif ; il faut justifier comment il sait ce qu’il raconte (scènes auxquelles il n’assiste pas).',
    examples:'*Le Grand Meaulnes* (Alain-Fournier), raconté par François Seurel ; *Gatsby le Magnifique* (F. Scott Fitzgerald) ; les aventures de Sherlock Holmes racontées par Watson.' },
  { key:'segunda-pessoa', name:'Deuxième personne',
    desc:'La narration s’adresse à un « tu » ou à un « vous », placé au centre de l’action : le lecteur lui-même, un personnage interpellé, ou le narrateur qui se parle.',
    forces:'Effet d’immersion et d’étrangeté ; convient aux textes courts, expérimentaux ou confessionnels ; le « vous » donne une distance froide, le « tu » une intimité accusatrice.',
    risks:'Lasse sur la durée ; peut provoquer une résistance chez le lecteur, qui refuse d’être « vous ».',
    examples:'*La Modification* (Michel Butor), entièrement au « vous » ; *Un homme qui dort* (Georges Perec), au « tu » ; *Si par une nuit d’hiver un voyageur* (Italo Calvino).' },
  { key:'terceira-omnisciente', name:'Troisième personne omnisciente',
    desc:'Un narrateur extérieur qui sait tout : les pensées de plusieurs personnages, le passé, l’avenir et ce que personne n’a vu. C’est la « focalisation zéro » de Genette.',
    forces:'Ampleur épique ; liberté de commenter, d’anticiper, de passer d’un personnage et d’une époque à l’autre ; idéal pour les fresques.',
    risks:'Distance émotionnelle ; des sauts d’une tête à l’autre mal maîtrisés désorientent le lecteur ; tentation du commentaire moralisateur.',
    examples:'*Le Père Goriot* (Honoré de Balzac), *Les Misérables* (Victor Hugo), *Germinal* (Émile Zola), *Guerre et Paix* (Léon Tolstoï).' },
  { key:'terceira-limitada', name:'Troisième personne limitée',
    desc:'Récit en « il / elle », mais collé à la perception d’un seul personnage à la fois (le Personnage POV). C’est la focalisation interne en troisième personne.',
    forces:'Équilibre entre intimité et souplesse ; permet d’alterner les points de vue d’une Scène ou d’un Chapitre à l’autre ; se marie avec le discours indirect libre.',
    risks:'Exige de la discipline : rien ne peut être raconté que le Personnage POV ne perçoive, ne sache ou ne suppose.',
    examples:'*Bel-Ami* (Guy de Maupassant), presque tout entier vu par Georges Duroy ; *Thérèse Desqueyroux* (François Mauriac) ; *1984* (George Orwell) ; la série *Harry Potter* (J. K. Rowling).' },
  { key:'terceira-objetiva', name:'Troisième personne objective (caméra)',
    desc:'Le narrateur ne rapporte que ce qui se voit et s’entend, comme une caméra, sans accès aux pensées. C’est la focalisation externe de Genette.',
    forces:'Sous-texte et tension ; le lecteur déduit les émotions des gestes et des répliques ; froideur et neutralité voulues.',
    risks:'Peut paraître glacial ; demande un dialogue et des gestes très expressifs ; difficile à tenir sur un roman entier.',
    examples:'*Collines comme des éléphants blancs* et *Les Tueurs* (Ernest Hemingway) ; *La Jalousie* (Alain Robbe-Grillet), où un regard décrit sans jamais se nommer ; les romans « durs » de Georges Simenon.' },
  { key:'nao-fiavel', name:'Narrateur non fiable',
    desc:'Un narrateur dont la version des faits ne mérite pas une pleine confiance — par mensonge, aveuglement, naïveté, folie ou intérêt.',
    forces:'Ironie dramatique, retournements, relecture ; le lecteur devient enquêteur et compare ce qui est dit avec ce qui transparaît.',
    risks:'Les indices doivent être loyaux : une révélation gratuite passe pour de la tricherie ; trop d’indices éventent la surprise.',
    examples:'*Le Meurtre de Roger Ackroyd* (Agatha Christie), *La Chute* (Albert Camus), *Lolita* (Vladimir Nabokov), *Les Vestiges du jour* (Kazuo Ishiguro).' },
  { key:'multiplos', name:'Narrateurs multiples (polyphonie)',
    desc:'L’histoire est partagée entre plusieurs voix ou plusieurs points de vue, qui se complètent ou se contredisent.',
    forces:'Montre un même monde sous des angles différents ; parfait pour les récits à plusieurs Arcs narratifs ; crée de l’ironie entre les versions.',
    risks:'Des voix trop semblables brouillent la lecture ; certains fils intéressent moins que d’autres et le lecteur les saute.',
    examples:'*Tandis que j’agonise* (William Faulkner), quinze voix pour un enterrement ; *Le Trône de fer* (George R. R. Martin) ; *Les Liaisons dangereuses* (Laclos), polyphonie par lettres.' },
  { key:'epistolar', name:'Récit épistolaire ou documentaire',
    desc:'Le récit est composé de lettres, de journaux intimes, de messages, de rapports, de procès-verbaux ou d’autres documents.',
    forces:'Vraisemblance et proximité ; chaque document a sa voix et son destinataire ; les vides entre les pièces créent le suspense et l’ironie.',
    risks:'L’action est toujours racontée « après coup » ; il faut justifier pourquoi quelqu’un écrit tout cela, et à ce moment-là.',
    examples:'*Les Liaisons dangereuses* (Choderlos de Laclos), *Lettres persanes* (Montesquieu), *Julie ou la Nouvelle Héloïse* (Jean-Jacques Rousseau), *Dracula* (Bram Stoker).' },
  { key:'fluxo-consciencia', name:'Flux de conscience',
    desc:'La narration imite l’écoulement continu des pensées, sensations et souvenirs d’un personnage, souvent sans ordre logique ni ponctuation régulière. La forme la plus radicale du monologue intérieur.',
    forces:'Profondeur psychologique maximale ; le temps intérieur l’emporte sur le temps de l’horloge.',
    risks:'Exigeant pour le lecteur ; l’intrigue et la clarté peuvent se dissoudre.',
    examples:'*Les lauriers sont coupés* (Édouard Dujardin, 1887), que Joyce reconnaissait comme modèle ; *Ulysse* (James Joyce) ; *Mrs Dalloway* (Virginia Woolf) ; *Le Bruit et la Fureur* (William Faulkner).' },
  { key:'primeira-plural', name:'Première personne du pluriel (« nous »)',
    desc:'Celui qui raconte est un groupe — un village, une classe, une génération — qui parle d’une seule voix et observe quelqu’un de l’extérieur.',
    forces:'Donne la parole à une communauté, avec ses commérages et sa culpabilité partagée ; effet de chœur et de légende.',
    risks:'Le « nous » n’a ni corps ni scènes propres ; difficile à tenir au-delà de la nouvelle ou du roman bref.',
    examples:'*Madame Bovary* (Gustave Flaubert), dont les premières pages sont dites par les camarades de classe de Charles (« Nous étions à l’Étude… ») ; *Virgin Suicides* (Jeffrey Eugenides) ; *Une rose pour Emily* (William Faulkner).' },
  { key:'intruso', name:'Narrateur intrusif (commentateur)',
    desc:'Un narrateur qui interrompt l’histoire pour la commenter, juger, digresser et converser avec le lecteur.',
    forces:'Voix pleine de personnalité, d’humour et de complicité ; permet l’ironie, les jugements, les sauts dans le temps à volonté.',
    risks:'Brise l’immersion ; si le commentaire vaut moins que l’histoire, le lecteur s’impatiente.',
    examples:'*Jacques le Fataliste et son maître* (Denis Diderot), *Le Rouge et le Noir* (Stendhal), les romans de Balzac, *Tom Jones* (Henry Fielding).' }
);

(() => {
  /* Notions qui accompagnent les types de narrateur */
  const CONCEPTS = [
    { n:'Auteur, narrateur et narrataire', a:'Instances du récit',
      d:'L’auteur est la personne réelle qui écrit ; le narrateur est la voix inventée qui raconte ; le narrataire est le destinataire auquel cette voix s’adresse à l’intérieur du texte (le « lecteur » interpellé, le destinataire d’une lettre, un juge, un enfant).',
      u:'Décidez à qui parle le narrateur, et pourquoi : c’est ce qui justifie le ton, ce qu’on explique et ce qu’on tait. On ne raconte pas la même histoire à un confesseur et à un tribunal.',
      c:'Confondre auteur et narrateur produit des narrateurs sans personnalité — ou des lecteurs qui attribuent à l’auteur les opinions du personnage (Céline, Houellebecq, Nabokov en ont fait les frais).',
      x:['*La Chute* (Camus) : Clamence parle à un inconnu rencontré dans un bar d’Amsterdam, qui ne répond jamais.', '*Le Père Goriot* (Balzac) interpelle le lecteur qui tient le livre « d’une main blanche ».', '*Les Mille et Une Nuits* : Shéhérazade raconte au sultan — le narrataire décide si elle vivra.'],
      s:['Narrateur non fiable', 'Récit épistolaire ou documentaire', 'Voix narrative', 'Narrateur intrusif (commentateur)'] },
    { n:'Statut du narrateur', a:'Hétérodiégétique · homodiégétique · autodiégétique (Genette)',
      d:'Classement de Gérard Genette (*Figures III*, 1972), enseigné en France. Hétérodiégétique : le narrateur est absent de l’histoire qu’il raconte. Homodiégétique : il y participe comme personnage secondaire ou témoin. Autodiégétique : il en est le héros. Genette distingue aussi le niveau : extradiégétique (le narrateur premier) et intradiégétique (un personnage qui raconte à son tour un récit enchâssé).',
      u:'Servez-vous-en pour vérifier la légitimité de la voix : d’où le narrateur tient-il ce qu’il sait ? Celui qui a participé ne connaît que ce qu’il a vu, entendu ou appris.',
      c:'Ne pas confondre avec la personne grammaticale : un narrateur hétérodiégétique peut dire « je » pour commenter sans jamais entrer dans l’action.',
      x:['Hétérodiégétique : *Germinal* (Zola).', 'Homodiégétique : François Seurel dans *Le Grand Meaulnes* ; Watson chez Conan Doyle.', 'Autodiégétique : *L’Étranger* (Camus) ; *À la recherche du temps perdu* (Proust).', 'Intradiégétique : Des Grieux racontant son histoire à l’homme de qualité dans *Manon Lescaut* (abbé Prévost).'],
      s:['Première personne — protagoniste', 'Première personne — témoin', 'Focalisation', 'Mise en abyme'] },
    { n:'Focalisation', a:'Point de vue · perspective narrative',
      d:'Répond à la question « qui perçoit ? » (et non « qui parle ? »). Focalisation zéro (omnisciente) : le narrateur en sait plus que tous les personnages. Focalisation interne : l’information passe par le filtre d’un personnage — fixe (toujours le même), variable (elle change d’une partie à l’autre) ou multiple (le même événement vu par plusieurs). Focalisation externe : le narrateur en sait moins que les personnages et n’enregistre que le visible.',
      u:'Choisissez la focalisation scène par scène selon ce que le lecteur doit savoir et ressentir. L’interne donne l’intimité, l’externe le mystère, la focalisation zéro l’ampleur et l’ironie.',
      c:'Changer de focalisation sans intention ni signal clair désoriente. À l’école, on parle souvent de « point de vue omniscient / interne / externe » : ce sont les mêmes notions.',
      x:['Zéro : *Le Père Goriot* (Balzac), avec sa longue présentation de la pension Vauquer.', 'Interne fixe : *Le Procès* (Kafka), collé à Joseph K.', 'Interne variable : *Madame Bovary* passe de Charles à Emma, puis à d’autres.', 'Interne multiple : *Rashōmon* (Kurosawa), le même crime en versions incompatibles.', 'Externe : l’ouverture de *Les Tueurs* (Hemingway).'],
      t:'Chaque Scène a son Personnage POV : c’est la focalisation interne de la Scène. La fiche du Personnage montre les Scènes dont il est le point de vue.',
      s:['Troisième personne limitée', 'Troisième personne omnisciente', 'Troisième personne objective (caméra)', 'Sauts de point de vue', 'Effet Rashomon'] },
    { n:'Personnage POV', a:'Personnage focal · personnage point de vue',
      d:'Le personnage à travers les sens et les pensées duquel le lecteur vit une scène. On ne raconte que ce qu’il perçoit, sait, se rappelle ou suppose.',
      u:'Pour choisir le POV d’une scène : celui qui a le plus à perdre, celui qui en sait le moins (pour le suspense), ou celui qui va changer. Donnez à chaque POV son vocabulaire et ses obsessions.',
      c:'Trop de POV diluent l’attachement ; chaque nouveau point de vue doit apporter ce qu’aucun autre ne peut donner.',
      x:['*Le Trône de fer* (Martin) : un POV par chapitre, avec le nom du personnage en titre.', '*Mrs Dalloway* (Woolf) : la perspective glisse d’esprit en esprit dans les rues de Londres.', '*Les Misérables* (Hugo) : Waterloo vu de haut, puis Paris à hauteur de Gavroche.'],
      t:'Choisissez le Personnage POV dans la fiche de chaque Scène ; les Personnages POV sont signalés dans les listes.',
      s:['Focalisation', 'Narrateurs multiples (polyphonie)', 'Sauts de point de vue'] },
    { n:'Distance narrative', a:'Distance psychique (John Gardner)',
      d:'Le degré de proximité entre le lecteur et la conscience du personnage — du plan d’ensemble au gros plan intérieur. Le même instant peut être raconté de très loin ou du dedans de la tête du personnage.',
      u:'Faites varier la distance comme une caméra : reculez pour situer et résumer, approchez dans les moments d’émotion. Changez progressivement, pas par à-coups.',
      c:'Passer de très loin à très près dans la même phrase sonne comme une erreur ; une distance toujours identique rend le texte monotone.',
      x:['Loin : « C’était l’hiver 1853. Un homme de grande taille sortit dans la rue. »', 'Plus près : « Henri détestait les tempêtes de neige. »', 'Dedans : « Mon Dieu, qu’il haïssait cette maudite neige. »', 'Flux : « La neige. Sous le col, dans les souliers, jusqu’à l’âme, misère. »'],
      s:['Discours indirect libre', 'Monologue intérieur', 'Flux de conscience'] },
    { n:'Temps de la narration', a:'Narration ultérieure · simultanée · antérieure · intercalée (Genette)',
      d:'La position temporelle du narrateur par rapport à ce qu’il raconte. Ultérieure : après coup (au passé — le cas le plus courant). Simultanée : pendant (au présent). Antérieure : avant (prophéties, rêves, prédictions). Intercalée : par épisodes, entre les événements (journaux, lettres).',
      u:'Le passé simple donne de la perspective et permet au narrateur de connaître la fin ; le présent donne l’urgence et l’incertitude. Dans la narration intercalée, le narrateur ignore la suite, d’où un suspense authentique.',
      c:'Le présent fatigue sur un long roman et rend le sommaire difficile ; alterner les temps sans critère semble négligé. En français, le choix passé simple / passé composé change aussi la voix (*L’Étranger* doit sa sécheresse au passé composé).',
      x:['Ultérieure : *À la recherche du temps perdu* — le narrateur adulte se souvient de l’enfant.', 'Simultanée : *Hunger Games* (Suzanne Collins).', 'Antérieure : les prédictions des sorcières dans *Macbeth*.', 'Intercalée : *Les Liaisons dangereuses* ; le *Journal* d’Anne Frank.'],
      s:['Récit épistolaire ou documentaire', 'Prolepse', 'Temps verbaux comme effet de style'] },
    { n:'Voix narrative', a:'La voix · le « ton » d’un narrateur',
      d:'La personnalité audible de celui qui raconte : son vocabulaire, son rythme, son humour, ce qu’il remarque et ce qu’il passe sous silence. C’est ce qui permet de reconnaître un narrateur en une seule phrase.',
      u:'Définissez trois choses : comment il parle (registre et rythme), ce qu’il remarque (obsessions), ce qu’il pense de lui-même (illusions). Lisez à voix haute : une voix s’entend.',
      c:'Une voix forte n’est pas une accumulation de tics ; un mot fétiche à chaque paragraphe lasse.',
      x:['Bardamu dans *Voyage au bout de la nuit* (Céline) : oralité, argot, points de suspension, rage.', 'Momo dans *La Vie devant soi* (Émile Ajar) : la logique d’un enfant qui détourne les mots des adultes.', 'Holden Caulfield dans *L’Attrape-cœurs* : argot adolescent et mépris des « faux jetons ».'],
      s:['Registres de langue', 'Ton', 'Idiolecte et marques d’oralité', 'Style oral (skaz)'] },
    { n:'Sauts de point de vue', a:'Head-hopping · changement de focalisation intempestif',
      d:'Passage brusque et non signalé du point de vue d’un personnage à celui d’un autre dans la même scène. À distinguer de l’omniscience maîtrisée, où un narrateur doté d’une voix propre conduit le lecteur d’un esprit à l’autre.',
      u:'En troisième personne limitée, gardez un POV par scène et ne changez qu’à une coupure de Scène ou de Chapitre. Si vous avez besoin de ce que pense un autre personnage, montrez-le par ses gestes et ses répliques.',
      c:'Tout changement n’est pas une faute : Flaubert, Woolf ou Tolstoï le font avec des transitions soignées. Le problème est le saut que le lecteur ne suit pas.',
      x:['Problème : « Anne sourit, certaine de l’avoir dupé. Paul, lui, avait tout compris et pensait déjà à sa vengeance. »', 'Solution : « Anne sourit, certaine de l’avoir dupé. Paul lui rendit son sourire — un peu trop lentement. »'],
      s:['Personnage POV', 'Troisième personne limitée', 'Sous-texte'] }
  ];

  SUPPORT.push({ key:'narrador', name:'Types de narrateur', kicker:'Narrateur',
    intro:'Qui raconte l’histoire, et d’où la voit-il ? C’est la première grande décision d’un livre, car elle détermine ce que le lecteur peut savoir, de qui il se sent proche et à qui il fait confiance. Les types ci-dessous peuvent être choisis dans la fiche de chaque Tome ; les notions qui suivent, en grande partie issues de Gérard Genette, aident à affiner ce choix.',
    groups:[
      { name:'Types de narrateur', items:NARRATORS.map(n => ({ n:n.name, d:n.desc, f:n.forces, c:n.risks, x:[n.examples] })) },
      { name:'Notions de voix et de point de vue', items:CONCEPTS }
    ]});
})();

/* ============ FIGURES DE STYLE ============ */
SUPPORT.push({ key:'figuras', name:'Figures de style', kicker:'Figure',
  intro:'On dit aussi figures de rhétorique. La tradition française, de Dumarsais (*Des tropes*, 1730) à Fontanier (*Les Figures du discours*, 1821-1830), distingue les tropes, qui changent le sens d’un mot (métaphore, métonymie…), et les figures qui jouent sur le son, la construction ou la pensée. Ce sont des écarts volontaires par rapport à l’usage courant, pour dire plus, plus fort ou plus juste. Une figure ne vaut que si elle fait voir ou sentir au lecteur ce que la phrase directe ne ferait pas.',
  groups:[
  { name:'Figures de sonorité', items:[
    { n:'Allitération', d:'Répétition d’un même son consonantique dans des mots proches.',
      u:'Choisissez les consonnes selon ce que vous décrivez : sifflantes (s, z, ch) pour le vent, le secret ou la menace ; occlusives (p, t, k, b, d, g) pour les coups et les chocs ; liquides (l, r) pour ce qui coule ou roule.',
      c:'En prose, plus de trois ou quatre mots d’affilée font virelangue ; une allitération involontaire (« ses sœurs sont sottes ») fait sourire au mauvais moment.',
      x:['« Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine, *Andromaque*) — les sifflantes font entendre les serpents.', '« Le vent violent vidait les venelles. »', '« Les chaussettes de l’archiduchesse sont-elles sèches ? » (virelangue).'],
      s:['Assonance', 'Harmonie imitative', 'Onomatopée', 'Rythme de la phrase'] },
    { n:'Assonance', d:'Répétition d’un même son vocalique dans des mots proches.',
      u:'Les voyelles claires et ouvertes (a, è, i) donnent éclat et légèreté ; les sombres et nasales (ou, on, an) donnent lenteur, gravité, mélancolie.',
      c:'En poésie, « assonance » désigne aussi la rime imparfaite où seule la dernière voyelle tonique concorde (chansons de geste) : ne pas confondre les deux sens.',
      x:['« Les sanglots longs / Des violons / De l’automne » (Verlaine, *Chanson d’automne*) — les nasales en « on » prolongent la plainte.', '« Un long son sourd montait du fond du puits. »'],
      s:['Allitération', 'Harmonie imitative', 'Rythme de la phrase'] },
    { n:'Harmonie imitative', a:'Allitération ou assonance expressive',
      d:'Combinaison de sons choisie pour imiter le bruit, le mouvement ou l’impression de ce que la phrase décrit. Nom traditionnel en France pour l’allitération et l’assonance mises au service du sens.',
      u:'Réservez-la aux moments où le son compte : une tempête, une machine, un galop, un murmure. Associez sons et rythme (phrase brève et heurtée pour la chute, longue et fluide pour la rivière).',
      c:'L’effet s’évente s’il est trop appuyé ; le lecteur doit le sentir avant de le remarquer.',
      x:['Le vers de Racine sur les serpents (*Andromaque*).', 'Les nasales de Verlaine, qui font gémir les violons.', '« Le train cognait, cognait, cahotait dans la nuit. »'],
      s:['Allitération', 'Assonance', 'Onomatopée'] },
    { n:'Onomatopée', d:'Mot ou suite de sons qui imite le bruit de ce qu’il désigne.',
      u:'Au-delà des interjections (boum, crac, tic-tac, plouf), préférez les verbes et noms d’origine onomatopéique, qui s’intègrent à la phrase : chuchoter, susurrer, cliqueter, crisser, grincer, vrombir, clapoter, glouglou, froufrou.',
      c:'L’onomatopée brute a un effet enfantin ou de bande dessinée — parfait si c’est ce que vous voulez. Attention : elles changent d’une langue à l’autre (le coq fait « cocorico » en France, « cock-a-doodle-doo » en anglais).',
      x:['« Le tic-tac de la pendule emplissait le salon. »', '« Les clés cliquetèrent dans sa poche. »', 'Les bulles d’Hergé : « Boum ! », « Vlan ! », « Tonnerre de Brest ! »'],
      s:['Harmonie imitative', 'Allitération', 'Images sensorielles'] },
    { n:'Paronomase', d:'Rapprochement de mots dont le son est voisin mais le sens différent (paronymes).',
      u:'Fonctionne dans les titres, les maximes, les slogans, l’humour et les répliques des personnages spirituels : le rapprochement des sons suggère un rapport entre les idées.',
      x:['« Et la mer et l’amour ont l’amer pour partage » (Pierre de Marbeuf, XVIIe siècle).', '« Qui vole un œuf vole un bœuf » (proverbe).', '« Traduttore, traditore » — traducteur, traître (proverbe italien).'],
      s:['Jeu de mots', 'Antanaclase', 'Allitération'] }
  ]},
  { name:'Figures de construction', items:[
    { n:'Anaphore', d:'Répétition d’un même mot ou groupe de mots au début de phrases, de vers ou de membres de phrase successifs.',
      u:'Crée l’insistance, le rythme de litanie, la montée émotionnelle. Bonne pour les discours, les imprécations, l’énumération des pertes, les obsessions d’un personnage.',
      c:'Après trois ou quatre reprises, brisez le motif : c’est la rupture qui frappe.',
      x:['« Rome, l’unique objet de mon ressentiment ! / Rome, à qui vient ton bras d’immoler mon amant ! » (Corneille, *Horace*).', '*Liberté* (Paul Éluard), dont presque chaque vers s’ouvre sur « Sur » avant d’aboutir au mot du titre.','« C’était le meilleur des temps, c’était le pire des temps » (Dickens, *Le Conte de deux cités*).'],
      s:['Épiphore', 'Parallélisme', 'Rythme ternaire', 'Répétition et refrain'] },
    { n:'Épiphore', a:'Épistrophe',
      d:'Répétition d’un même mot ou groupe de mots à la fin de phrases ou de vers successifs.',
      u:'La fin de phrase est la place forte : y répéter un mot martèle une idée fixe.',
      x:['« Il voulait la maison. Il rêvait de la maison. Il aurait tué pour la maison. »', '« Je n’ai rien dit. Elle n’a rien dit. Nous n’avons jamais rien dit. »'],
      s:['Anaphore', 'Anadiplose', 'Place forte de la phrase'] },
    { n:'Anadiplose', d:'Reprise, au début d’une phrase ou d’un vers, du mot qui terminait le précédent.',
      u:'Crée un enchaînement — de causes, de pensées, de marches qu’on descend. Bonne pour les raisonnements obsessionnels et les engrenages.',
      x:['« La peur mène à la colère, la colère mène à la haine, la haine… mène à la souffrance » (Yoda, *La Menace fantôme*).', '« Il ouvrit la porte. La porte donnait sur un couloir. Le couloir n’avait pas de fin. »'],
      s:['Épiphore', 'Gradation'] },
    { n:'Parallélisme', d:'Reprise d’une même structure syntaxique dans des phrases ou segments successifs.',
      u:'Range les idées en paires et en séries, rend les phrases mémorables et prépare le contraste : après deux membres identiques, le troisième peut surprendre.',
      x:['« Toutes les familles heureuses se ressemblent, mais chaque famille malheureuse l’est à sa façon » (Tolstoï, *Anna Karénine*).', '« L’homme n’est ni ange ni bête » (Pascal, *Pensées*).', '« Il parlait trop, il buvait trop, il aimait trop. »'],
      s:['Anaphore', 'Antithèse', 'Chiasme', 'Rythme ternaire'] },
    { n:'Chiasme', d:'Reprise de deux éléments dans l’ordre inverse, en croix (A-B / B-A).',
      u:'Donne l’allure d’une sentence close sur elle-même : idéal pour les maximes, les dilemmes et les répliques finales.',
      c:'Figure très voyante : un par chapitre, c’est déjà beaucoup.',
      x:['« Il faut manger pour vivre, et non pas vivre pour manger » (Molière, *L’Avare*).', '« Un pour tous, tous pour un » (Dumas, *Les Trois Mousquetaires*).', '« Elle vivait pour écrire ; elle écrivait pour vivre. »'],
      s:['Parallélisme', 'Antithèse'] },
    { n:'Asyndète', d:'Suppression des mots de liaison (conjonctions) entre des termes ou des propositions coordonnés.',
      u:'Accélère : actions rapides, énumérations sèches, panique, efficacité. Le lecteur fait lui-même les liens.',
      x:['« Je suis venu, j’ai vu, j’ai vaincu » (César, *Veni, vidi, vici*).', '« Il courut, trébucha, tomba, se releva. »'],
      s:['Polysyndète', 'Parataxe et hypotaxe', 'Rythme de la phrase'] },
    { n:'Polysyndète', d:'Répétition insistante d’une même conjonction (le plus souvent « et », « ni » ou « ou »).',
      u:'Ralentit et accumule : fatigue, abondance, parole d’enfant, ton biblique, émerveillement.',
      x:['« Et il pleut, et il vente, et la maison craque, et personne ne vient. »', '« Il n’avait ni toit, ni pain, ni nom, ni personne pour le pleurer. »', 'Les litanies de Charles Péguy, faites de « et » qui avancent comme une marche.'],
      s:['Asyndète', 'Énumération'] },
    { n:'Ellipse (figure)', d:'Omission d’un ou de plusieurs mots que le contexte permet de rétablir.',
      u:'Condense et donne du naturel, surtout dans le dialogue : personne ne parle par phrases complètes.',
      x:['« Dans le salon, deux ou trois invités. » (on sous-entend « il y avait »)', '« — Un café ? — Sans sucre. »', '« À chacun son métier. »'],
      s:['Zeugme', 'Ellipse narrative', 'Phrase nominale'] },
    { n:'Zeugme', a:'Zeugma · attelage',
      d:'Un même terme (souvent le verbe) régit plusieurs compléments mais n’est exprimé qu’une fois. Quand il relie un sens concret et un sens abstrait, on parle de zeugme sémantique (ou attelage), source d’humour ou de poésie.',
      u:'Le zeugme qui mêle les plans est une arme classique de l’ironie : il met sur le même rang ce qui ne devrait pas l’être.',
      x:['« Vêtu de probité candide et de lin blanc » (Hugo, *Booz endormi*).', '« Il perdit son chapeau et son sang-froid. »', '« Elle prit le train et la décision de ne jamais revenir. »'],
      s:['Ellipse (figure)', 'Ironie'] },
    { n:'Inversion', a:'Anastrophe',
      d:'Modification de l’ordre habituel des mots (sujet-verbe-complément), par exemple en plaçant le complément ou l’attribut en tête, ou le sujet après le verbe.',
      u:'Met en relief ce qui passe en tête ou en fin de phrase et donne un ton solennel ou ancien. Utile pour les voix d’époque, les prophéties, les narrateurs épiques. Le français pratique aussi l’inversion naturelle après certains adverbes (« Peut-être viendra-t-il », « Ainsi parlait… »).',
      c:'Excessive, elle rend la phrase précieuse ou énigmatique. Attention à ne pas la confondre avec l’hyperbate, qui a en français un autre sens.',
      x:['« Longue fut la nuit. »', '« Bien mal acquis ne profite jamais » (proverbe).', '« Grande fut sa surprise lorsqu’il ouvrit la lettre. »'],
      s:['Hyperbate', 'Archaïsme', 'Place forte de la phrase'] },
    { n:'Hyperbate', d:'Dans la rhétorique française, ajout d’un ou de plusieurs éléments à une phrase qui semblait terminée, ce qui les met en relief. (Ailleurs, et en portugais ou en espagnol, le mot désigne plutôt l’inversion.)',
      u:'L’élément rajouté après le point d’arrivée attendu frappe comme un repentir ou une confidence. Très efficace pour l’ironie et l’émotion retenue.',
      c:'Ne pas en faire un tic de fin de phrase ; une seule hyperbate par page suffit.',
      x:['« Il était beau, et riche, et seul. »', '« La nuit tombait. Et la neige. »', '« Elle l’avait aimé. Un peu. »'],
      s:['Inversion', 'Place forte de la phrase', 'Épanorthose'] },
    { n:'Pléonasme', d:'Répétition d’une idée déjà contenue dans un autre mot, pour la renforcer.',
      u:'Le pléonasme expressif intensifie (« je l’ai vu de mes yeux »). Il peut caractériser un personnage qui s’emporte ou qui insiste.',
      c:'Le pléonasme fautif n’est que redondance : « monter en haut », « prévoir à l’avance », « au jour d’aujourd’hui », « s’avérer vrai », « voire même ».',
      x:['« Je l’ai vu, dis-je, vu, de mes propres yeux vu, / Ce qu’on appelle vu » (Molière, *Tartuffe*).', '« Il pleura des larmes amères. »'],
      s:['Hyperbole', 'Répétition et refrain'] },
    { n:'Anacoluthe', d:'Rupture dans la construction de la phrase : on commence d’une manière et on finit d’une autre, comme dans la parole spontanée.',
      u:'Imite l’oral, l’hésitation, l’émotion. Très utile dans les dialogues, les monologues intérieurs et les narrateurs populaires.',
      c:'Dans la narration neutre, une anacoluthe involontaire passe pour une faute (« En attendant votre réponse, veuillez agréer… »).',
      x:['« Le nez de Cléopâtre : s’il eût été plus court, toute la face de la terre aurait changé » (Pascal, *Pensées*).', '« Mon grand-père, personne n’osait lui dire non. »', '« Moi, ce qui m’énerve, c’est qu’il ne prévient jamais. »'],
      s:['Idiolecte et marques d’oralité', 'Monologue intérieur', 'Style oral (skaz)'] },
    { n:'Énumération', a:'Accumulation',
      d:'Succession de plusieurs éléments de même nature. On parle d’accumulation quand l’énumération est abondante, voire chaotique, et qu’elle produit un effet de profusion.',
      u:'Un inventaire caractérise vite : ce qu’il y a dans un tiroir, une valise, une table de chevet dit qui en est le propriétaire. Placez l’élément le plus fort à la fin.',
      x:['Les listes démesurées de Rabelais dans *Gargantua*.', 'Prévert, *Inventaire* ; Perec, *La Vie mode d’emploi*.', '« Dans sa valise : deux chemises, un chapelet, la photo de sa mère et un couteau. »'],
      s:['Gradation', 'Détail révélateur', 'Polysyndète', 'Maximalisme'] },
    { n:'Gradation', a:'Gradation ascendante ou descendante · anticlimax',
      d:'Suite de mots ou d’idées rangés par ordre d’intensité croissante ou décroissante.',
      u:'La gradation ascendante construit l’émotion ; la descendante la vide, et l’anticlimax soudain est un ressort comique.',
      x:['« Va, cours, vole, et nous venge » (Corneille, *Le Cid*).', '« C’est un roc ! … c’est un pic ! … c’est un cap ! » (Rostand, *Cyrano de Bergerac*).', 'Anticlimax : « Il perdit sa femme, sa fortune, son honneur et ses clés de voiture. »'],
      s:['Énumération', 'Rythme ternaire', 'Hyperbole', 'Cadence majeure et mineure'] },
    { n:'Polyptote', d:'Reprise d’un même mot sous plusieurs formes grammaticales (temps, personne, nombre, dérivés) dans une même phrase.',
      u:'Fait tourner une idée sur elle-même, comme une obsession ou un raisonnement serré. Très apprécié des moralistes.',
      x:['« …ce serait être fou par un autre tour de folie de n’être pas fou » (Pascal, *Pensées*).', '« Il aimait, il avait aimé, il aimerait toujours. »'],
      s:['Antanaclase', 'Répétition et refrain', 'Paradoxe'] }
  ]},
  { name:'Figures d’analogie et de substitution (tropes)', items:[
    { n:'Comparaison', d:'Rapprochement de deux réalités (le comparé et le comparant) au moyen d’un outil de comparaison : comme, tel, pareil à, semblable à, ressembler à, on aurait dit.',
      u:'La meilleure comparaison sort du monde du personnage : un marin compare avec la mer, une chirurgienne avec le bloc opératoire. L’image caractérise alors celui qui la fait.',
      c:'Fuyez les comparaisons toutes faites (« blanc comme neige », « rouge comme une tomate ») : elles ne font rien voir.',
      x:['« La terre est bleue comme une orange » (Paul Éluard) — la comparaison qui défie la logique.', '« Le Poète est semblable au prince des nuées » (Baudelaire, *L’Albatros*).', '« Vue d’avion, la ville ressemblait à une carte électronique. »'],
      s:['Métaphore', 'Images sensorielles', 'Cliché'] },
    { n:'Métaphore', d:'Désignation d’une réalité par le nom d’une autre qui lui ressemble, sans outil de comparaison : une chose n’est pas « comme » l’autre, elle est l’autre. La métaphore est dite in praesentia si le comparé est exprimé, in absentia s’il ne l’est pas.',
      u:'Une bonne métaphore est concrète, sensorielle, surprenante et juste. Elle peut se prolonger (métaphore filée) ou organiser un livre entier.',
      c:'Les métaphores incohérentes (« le char de l’État navigue sur un volcan », célèbre phrase de Monsieur Prudhomme chez Henry Monnier) et les métaphores mortes (« une marée humaine ») affaiblissent la prose.',
      x:['« Ma jeunesse ne fut qu’un ténébreux orage » (Baudelaire, *L’Ennemi*).', '« Cette faucille d’or dans le champ des étoiles » (Hugo, *Booz endormi*) — la lune, jamais nommée.', '« La mémoire est un grenier : on n’y monte que pour chercher autre chose. »'],
      s:['Comparaison', 'Métaphore filée', 'Allégorie', 'Symbole', 'Catachrèse'] },
    { n:'Métaphore filée', a:'Métaphore continuée',
      d:'Métaphore développée sur plusieurs phrases ou vers, en déclinant le champ lexical du comparant.',
      u:'Elle organise un paragraphe : une fois l’image posée, chaque mot du domaine choisi vient l’enrichir. Choisissez un comparant riche en vocabulaire concret (la guerre, la mer, le jardin, la cuisine).',
      c:'Filée trop longtemps, elle devient laborieuse ; si elle change de domaine en route, elle tourne à l’incohérence.',
      x:['Baudelaire, *L’Ennemi* : la jeunesse comme un jardin ravagé par l’orage, où il reste peu de « fruits vermeils ».', 'La « bête humaine » chez Zola : la locomotive décrite comme un animal qui halète et qui souffre.', '« La mère attaqua le plat, contourna l’oncle par la gauche et s’empara de la dernière pomme de terre. »'],
      s:['Métaphore', 'Champ lexical', 'Allégorie'] },
    { n:'Allégorie', d:'Représentation concrète et suivie d’une idée abstraite : un personnage, une scène ou un récit entier qui figure, point par point, une réalité morale, politique ou religieuse. En français, l’allégorie se signale souvent par une majuscule (la Mort, la Justice).',
      u:'Permet de parler du présent sans le nommer (utile sous la censure), d’incarner des idées, de créer des fables. Elle fonctionne mieux quand l’histoire littérale tient debout toute seule.',
      c:'Si chaque élément n’a qu’une seule lecture évidente, le texte devient rébus ou sermon.',
      x:['*Les Fables* de La Fontaine : le loup, l’agneau, la cour du lion.', '*La Peste* (Camus) : l’épidémie d’Oran se lit comme l’Occupation et le mal politique.', '*La Ferme des animaux* (Orwell) : la ferme est la Révolution russe.', 'La Mort à la faux ; Marianne pour la République.'],
      s:['Métaphore', 'Symbole', 'Personnification', 'Personnage type'] },
    { n:'Métonymie', d:'Désignation d’une chose par le nom d’une autre qui lui est liée par un rapport logique : l’auteur pour l’œuvre, le contenant pour le contenu, le lieu pour l’institution, la cause pour l’effet, la matière pour l’objet, le symbole pour la chose.',
      u:'Condense et déplace l’attention vers le détail concret. La description réaliste est au fond métonymique : elle montre la partie tangible d’un tout.',
      x:['« Lire un Zola. » (l’œuvre)', '« Boire un verre. » (le contenu)', '« L’Élysée a démenti. » / « Matignon temporise. » (la présidence, le gouvernement)', '« Il a quitté la robe pour l’épée. » (la justice, l’armée)'],
      s:['Synecdoque', 'Détail révélateur'] },
    { n:'Synecdoque', d:'Variété de métonymie fondée sur un rapport d’inclusion : la partie pour le tout, le tout pour la partie, le singulier pour le pluriel, la matière pour l’objet.',
      u:'Très cinématographique : filmer une foule par ses pieds, une armée par ses lances, un personnage par un détail.',
      x:['« Une voile à l’horizon. » (un navire)', '« Il avait cinq bouches à nourrir. »', '« Le Français est râleur. » (les Français)', '« La France a battu le Brésil. » (l’équipe)'],
      s:['Métonymie', 'Détail révélateur'] },
    { n:'Personnification', a:'Animisme',
      d:'Attribution de qualités, de gestes ou de sentiments humains à un animal, un objet, une force naturelle ou une idée.',
      u:'Donne vie au décor et projette sur lui l’état d’esprit du personnage.',
      c:'Excessive, elle rend tout sentimental ou mièvre.',
      x:['« Sois sage, ô ma Douleur, et tiens-toi plus tranquille » (Baudelaire, *Recueillement*).', '« La maison gémissait à chaque rafale. »', '« La mort frappa à sa porte ; il fit semblant de ne pas être là. »'],
      s:['Prosopopée', 'Paysage état d’âme', 'Hypallage', 'Apostrophe'] },
    { n:'Prosopopée', d:'Figure par laquelle on fait parler un absent, un mort, un animal, une chose ou une abstraction. La tradition française la distingue de la simple personnification : ici, l’être inanimé ou disparu prend la parole.',
      u:'Elle donne une voix à ce qui n’en a pas — un mort qui juge les vivants, une ville qui se plaint, la Nature qui répond. Puissante dans les plaidoyers, les éloges funèbres, les fantômes.',
      c:'Pompeuse si elle n’est pas préparée ; elle demande un contexte grave ou franchement ludique.',
      x:['La « prosopopée de Fabricius » dans le *Discours sur les sciences et les arts* (Rousseau) : un héros romain ressuscité accuse Rome.', 'Au sens large, les animaux qui raisonnent et discutent dans les *Fables* de La Fontaine.','« Et la vieille maison dit : “Vous m’avez oubliée.” »'],
      s:['Personnification', 'Apostrophe'] },
    { n:'Synesthésie', a:'Correspondances',
      d:'Association, dans une même image, de sensations relevant de sens différents.',
      u:'Rend les perceptions neuves et intenses ; utile pour les états altérés, les souvenirs d’enfance, la musique, la nourriture, le désir.',
      x:['« Les parfums, les couleurs et les sons se répondent » (Baudelaire, *Correspondances*).', '« A noir, E blanc, I rouge, U vert, O bleu : voyelles » (Rimbaud, *Voyelles*).', '« Une voix rugueuse et sombre. » / « L’odeur verte de l’herbe coupée. »'],
      s:['Images sensorielles', 'Hypallage', 'Impressionnisme littéraire'] },
    { n:'Hypallage', d:'Attribution à un mot d’une qualité qui revient logiquement à un autre mot de la même phrase.',
      u:'Avec un seul adjectif déplacé, on caractérise à la fois l’objet et la personne, et l’on crée un léger vertige.',
      x:['« Ibant obscuri sola sub nocte » (Virgile) : « Ils allaient obscurs sous la nuit solitaire » — ce sont eux, les solitaires.', '« Ce marchand accoudé sur son comptoir avide » (vers de Victor Hugo, exemple scolaire classique).', '« Il monta l’escalier fatigué de l’immeuble. »'],
      s:['Adjectif expressif', 'Personnification', 'Synesthésie'] },
    { n:'Antonomase', d:'Remplacement d’un nom propre par une périphrase ou un nom commun qui l’identifie — ou emploi d’un nom propre comme nom commun.',
      u:'Varie la désignation, glorifie ou ridiculise. Les surnoms des personnages sont des antonomases, et ils caractérisent autant celui qui les donne.',
      x:['« Un harpagon », « un tartuffe », « un don juan », « une mégère » : la littérature a fourni des noms communs.', '« L’Aigle de Meaux » (Bossuet) ; « le Roi-Soleil » (Louis XIV) ; « la Ville lumière » (Paris).', '« Il se prend pour Sherlock. »'],
      s:['Périphrase', 'Noms des personnages', 'Personnage type'] },
    { n:'Périphrase', a:'Circonlocution',
      d:'Expression de ce qu’un seul mot pourrait dire au moyen de plusieurs mots.',
      u:'Évite les répétitions, ennoblit, adoucit ou ironise. Elle caractérise aussi les personnages pompeux, bureaucratiques ou évasifs.',
      c:'Le mot exact est presque toujours plus fort. Molière a ridiculisé l’abus de périphrases chez les précieuses, qui auraient appelé les fauteuils « les commodités de la conversation ».',
      x:['« La langue de Molière » (le français) ; « l’astre du jour » (le soleil) ; « le billet vert » (le dollar).', '« Les forces de l’ordre », « les techniciens de surface » : la périphrase administrative.', '« Le précieux liquide » : périphrase usée, tic journalistique à éviter.'],
      s:['Antonomase', 'Euphémisme', 'Cliché', 'Baroque, préciosité et burlesque'] },
    { n:'Symbole', d:'Objet, être, couleur ou geste concret qui, sans cesser d’être ce qu’il est, prend un sens abstrait au-delà du littéral.',
      u:'Les symboles les plus forts naissent dans l’histoire : un objet banal qui revient aux moments décisifs et se charge de sens. Présentez-le d’abord comme une simple chose.',
      c:'Expliquer le symbole le tue. Les symboles universels (colombe, rose rouge, corbeau) sont usés.',
      x:['La casquette de Charles Bovary, décrite en détail dès la première page : tout le personnage.', 'La lumière verte au bout du ponton dans *Gatsby le Magnifique*.', 'La baleine blanche de *Moby Dick* ; la conque de *Sa Majesté des Mouches*.'],
      s:['Motif récurrent', 'Allégorie', 'Corrélatif objectif'] },
    { n:'Catachrèse', a:'Métaphore lexicalisée',
      d:'Métaphore si bien intégrée à la langue qu’on ne la perçoit plus comme figure : c’est le nom ordinaire des choses, faute d’autre mot.',
      u:'Elle peut être réveillée si on la prend au pied de la lettre — ressort d’humour et de poésie.',
      x:['« Les pieds de la table », « les bras du fauteuil », « l’aile du nez », « une dent de scie », « à cheval sur le mur ».', 'Réveillée : « La table avait quatre pieds et aucune envie de marcher. »'],
      s:['Métaphore', 'Cliché'] },
    { n:'Antanaclase', d:'Reprise d’un même mot avec deux sens différents dans la même phrase.',
      u:'Tient du jeu de mots mais vise souvent la profondeur : le second sens éclaire ou contredit le premier. Idéale pour les maximes et les répliques qui restent.',
      x:['« Le cœur a ses raisons que la raison ne connaît point » (Pascal, *Pensées*).', '« Quand un Anglais joue, il joue ; quand il travaille, il travaille. »', '« Il faut payer les dettes de sa jeunesse — et sa jeunesse aussi. »'],
      s:['Jeu de mots', 'Paronomase', 'Polyptote'] }
  ]},
  { name:'Figures de pensée : opposition, insistance, atténuation', items:[
    { n:'Antithèse', d:'Rapprochement de deux mots ou de deux idées de sens opposé.',
      u:'Structure les conflits, les dilemmes et les portraits (ce que quelqu’un paraît / ce qu’il est). Le contraste rend chaque pôle plus net. C’est la figure-reine du romantisme de Hugo.',
      x:['« Je vis, je meurs : je me brûle et me noie » (Louise Labé, *Sonnets*).', '« Être ou ne pas être, telle est la question » (Shakespeare, *Hamlet*).', '« Il avait faim de tout et envie de rien. »'],
      s:['Oxymore', 'Paradoxe', 'Parallélisme', 'Contraste et juxtaposition', 'Faire-valoir'] },
    { n:'Oxymore', a:'Oxymoron · alliance de mots',
      d:'Réunion, dans une même expression, de deux termes qui se contredisent.',
      u:'Exprime en deux mots les émotions ambivalentes : l’amour, le deuil, le désir, la honte, l’extase.',
      x:['« Cette obscure clarté qui tombe des étoiles » (Corneille, *Le Cid*).', '« Le Soleil noir de la Mélancolie » (Nerval, *El Desdichado*).', '« Un silence assourdissant », « une douce violence », « un illustre inconnu ».'],
      s:['Antithèse', 'Paradoxe'] },
    { n:'Paradoxe', d:'Affirmation qui semble contraire à la logique ou au sens commun, mais qui contient une vérité.',
      u:'Bon pour les thèmes, les maximes de personnages sages ou cyniques, les slogans des mondes dystopiques.',
      x:['« Je est un autre » (Rimbaud, lettre à Paul Demeny).', '« Tous les animaux sont égaux, mais certains sont plus égaux que d’autres » (Orwell).', '« Qui veut faire l’ange fait la bête » (Pascal, *Pensées*).'],
      s:['Oxymore', 'Antithèse', 'Ironie'] },
    { n:'Ironie', a:'Ironie verbale · sarcasme (sa forme agressive)',
      d:'Dire une chose pour en faire entendre une autre, souvent le contraire. Elle repose sur la complicité du lecteur, qui doit percevoir l’écart entre le dit et le pensé.',
      u:'Distinguez l’ironie verbale (celle-ci), l’ironie de situation (le résultat contredit l’attente) et l’ironie dramatique (le lecteur en sait plus que le personnage). L’ironie du narrateur crée une distance critique : c’est l’arme de Voltaire, de Flaubert, de Stendhal, de Jane Austen.',
      c:'Sans indices de ton, elle est lue au premier degré ; continue, elle rend le narrateur antipathique.',
      x:['Le « meilleur des mondes possibles » que Pangloss proclame au milieu des catastrophes (*Candide*, Voltaire).', '« C’est une vérité universellement reconnue qu’un célibataire pourvu d’une belle fortune doit être en quête d’une épouse » (Austen, *Orgueil et Préjugés*).', 'Les « idées reçues » de Homais et de Bouvard et Pécuchet chez Flaubert.'],
      s:['Antiphrase', 'Ironie dramatique', 'Litote', 'Ton', 'Comique et humour', 'Style ironique'] },
    { n:'Antiphrase', d:'Forme la plus simple de l’ironie : employer un mot ou une phrase dans le sens contraire de son sens véritable.',
      u:'Très fréquente à l’oral, elle caractérise vite un personnage moqueur, exaspéré ou désabusé. Le contexte et le ton doivent rendre le renversement évident.',
      c:'À l’écrit, sans indice, l’antiphrase peut être prise au pied de la lettre.',
      x:['« C’est malin ! » (devant une bêtise)', '« Quel temps magnifique ! » (sous l’averse)', '« Bravo, c’est réussi. »'],
      s:['Ironie', 'Litote'] },
    { n:'Hyperbole', d:'Exagération volontaire de la réalité.',
      u:'Propre à la parole familière, à l’humour, au registre épique et aux personnages dramatiques. Elle caractérise celui qui l’emploie.',
      c:'Chez un narrateur sobre, une seule hyperbole détonne ; les hyperboles usées (« mort de rire », « génial ») ne portent plus.',
      x:['La tirade du nez dans *Cyrano de Bergerac* (Rostand) : le nez devient roc, pic, cap, péninsule.', 'Les géants de Rabelais : *Gargantua*, *Pantagruel* — l’hyperbole devenue récit.', '« Je te l’ai dit mille fois. »'],
      s:['Litote', 'Gradation', 'Comique et humour'] },
    { n:'Euphémisme', d:'Atténuation d’une idée désagréable, choquante ou taboue par une expression plus douce.',
      u:'Révèle la pudeur, la délicatesse, l’hypocrisie ou la peur. Les euphémismes d’un personnage — ou d’un régime — disent ce qu’on n’a pas le droit de dire dans ce monde-là.',
      x:['« Il nous a quittés. » / « Il s’est éteint. »', '« Plan de sauvegarde de l’emploi » (licenciements) ; « personne à mobilité réduite ».', '« Dommages collatéraux », « solution finale » : l’euphémisme au service de l’horreur.'],
      s:['Dysphémisme', 'Périphrase', 'Litote', 'Sous-texte'] },
    { n:'Dysphémisme', d:'Le contraire de l’euphémisme : expression crue, brutale ou dépréciative à la place d’un terme neutre.',
      u:'Donne de la dureté, de l’humour noir, de la révolte. Marque les personnages cyniques, les soldats, les médecins, les fossoyeurs.',
      x:['« Casser sa pipe », « passer l’arme à gauche », « manger les pissenlits par la racine ».', '« Ta poubelle à roulettes » (pour une voiture).'],
      s:['Euphémisme', 'Registres de langue', 'Humour noir'] },
    { n:'Litote', d:'Dire moins pour faire entendre plus, souvent en niant le contraire de ce qu’on veut dire.',
      u:'Ton retenu, pudique ou ironique ; typique des narrateurs discrets et de l’« understatement » britannique.',
      c:'À ne pas confondre avec l’euphémisme : la litote renforce par la retenue, l’euphémisme adoucit.',
      x:['« Va, je ne te hais point » (Corneille, *Le Cid*) — Chimène avoue son amour.', '« Ce n’est pas mauvais. » (c’est délicieux)', '« Il n’est pas tout à fait inconnu des services de police. »'],
      s:['Ironie', 'Euphémisme', 'Hyperbole'] },
    { n:'Apostrophe', a:'Invocation',
      d:'Interpellation directe d’une personne ou d’une chose — présente, absente, morte ou inanimée — en interrompant le discours.',
      u:'Fait monter brusquement l’émotion. Sert aussi au narrateur pour s’adresser au lecteur.',
      x:['« Ô temps ! suspends ton vol » (Lamartine, *Le Lac*).', '« Hypocrite lecteur, — mon semblable, — mon frère ! » (Baudelaire, *Au lecteur*).', '« Lecteur, je l’épousai » (Charlotte Brontë, *Jane Eyre*).'],
      s:['Personnification', 'Prosopopée', 'Métafiction', 'Deuxième personne'] },
    { n:'Question rhétorique', a:'Interrogation oratoire',
      d:'Question posée non pour obtenir une réponse mais pour affirmer avec plus de force, exprimer un doute ou impliquer le lecteur.',
      u:'En monologue intérieur, elle montre le personnage qui se débat. Dans la narration, elle pose la question que le lecteur se posait déjà.',
      c:'Plusieurs à la suite tournent au mélodrame.',
      x:['« Que diable allait-il faire dans cette galère ? » (Molière, *Les Fourberies de Scapin*).', '« Et qu’aurais-je pu faire d’autre ? »'],
      s:['Monologue intérieur', 'Apostrophe'] },
    { n:'Aposiopèse', a:'Réticence · suspension',
      d:'Interruption brusque de la phrase, qui laisse le reste sous-entendu.',
      u:'Hésitation, menace voilée, émotion qui coupe la voix, pudeur. Dans le dialogue, ce qui n’est pas dit est souvent le plus important.',
      c:'Les points de suspension en excès ramollissent la prose ; un point est souvent plus fort.',
      x:['« Quos ego… » — le « Je vais vous… » de Neptune aux vents déchaînés (Virgile, *Énéide*).', '« Si je te reprends dans cette maison… »', '« Il avait dit qu’il reviendrait, mais… »'],
      s:['Sous-texte', 'Ponctuation et effets de style'] },
    { n:'Prétérition', a:'Paralipse',
      d:'Feindre de ne pas parler d’une chose — tout en en parlant.',
      u:'Arme d’insinuation : parfaite pour les manipulateurs, les politiciens, les commères et les narrateurs peu innocents.',
      x:['« Je ne parlerai pas de l’argent que tu me dois. »', '« Je ne rappellerai à personne où il se trouvait cette nuit-là. »', 'Le discours de Marc Antoine dans *Jules César* (Shakespeare) : il vient enterrer César, « non le louer » — et le loue.'],
      s:['Ironie', 'Sous-texte', 'Narrateur non fiable'] },
    { n:'Épanorthose', a:'Correction',
      d:'Retour sur ce qu’on vient de dire pour le corriger, le nuancer ou le renforcer (« que dis-je », « ou plutôt », « mieux »).',
      u:'Donne l’illusion d’une pensée en train de se faire. Excellente pour la gradation comique, pour la mauvaise foi et pour les narrateurs scrupuleux.',
      x:['« Que dis-je, c’est un cap ? … C’est une péninsule ! » (Rostand, *Cyrano de Bergerac*).', '« Je l’aimais — non, je l’adorais. »', '« Il était en retard, ou plutôt il n’était pas venu. »'],
      s:['Gradation', 'Hyperbate', 'Hyperbole'] },
    { n:'Jeu de mots', a:'Calembour · double sens',
      d:'Exploitation des sens multiples d’un mot, ou de mots qui se prononcent de la même façon (homophones), pour créer l’humour ou l’ambiguïté. Le calembour est le jeu de mots fondé sur le son.',
      u:'Caractérise les personnages spirituels (ou insupportables), fournit des titres et peut cacher des indices à la vue de tous. La langue française, riche en homophones, s’y prête particulièrement.',
      c:'Presque toujours intraduisible ; en rafale, il fatigue.',
      x:['« Le roi n’est pas un sujet » — réponse attribuée au marquis de Bièvre, à qui l’on demandait un calembour sur le roi.', '*L’Importance d’être Constant* (Wilde) : en anglais, « Ernest » sonne comme « earnest », sérieux.', 'Les sketches de Raymond Devos et les contrepèteries du *Canard enchaîné*.'],
      s:['Paronomase', 'Antanaclase', 'Comique et humour'] }
  ]}
]});

/* ============ PROCÉDÉS DE STYLE ============ */
SUPPORT.push({ key:'estilo', name:'Procédés de style', kicker:'Style',
  intro:'Tout ce qui fait sonner un texte, au-delà des figures proprement dites : la manière de rapporter les paroles, la longueur et le rythme des phrases, le choix des mots, le ton, la description. Ce sont des décisions de prose : une même scène, avec les mêmes faits, peut s’écrire de cent façons — Queneau l’a prouvé en 99 dans *Exercices de style* —, et le style est la somme de ces choix.',
  groups:[
  { name:'Modes de discours', items:[
    { n:'Discours direct', a:'Style direct',
      d:'Reproduction littérale des paroles des personnages. En français, le dialogue s’ouvre en général par des guillemets, chaque changement d’interlocuteur étant marqué par un tiret en début de ligne ; beaucoup d’éditeurs contemporains se contentent des tirets. Le verbe de parole se place avant la réplique ou en incise, avec inversion du sujet (« dit-il »).',
      u:'Donne vie, rythme et présence à la scène. Préférez « dit » et « demanda », qui sont invisibles, et remplacez une partie des verbes de parole par des gestes. Coupez les politesses et les banalités : le dialogue de roman est de la conversation condensée.',
      c:'Un dialogue qui ne sert qu’à transmettre de l’information (« Comme tu le sais, Paul, notre père est mort il y a dix ans… ») est de l’exposition déguisée. Les règles typographiques précises (espaces, guillemets, tirets) se trouvent dans la section Ponctuation.',
      x:['« — Tu viens ? / — Oui. / — Quand ? / — Quand je pourrai. »', 'Incise : « Je ne sais pas, murmura-t-elle, je ne sais plus. »', 'Convention classique : guillemet ouvrant avant la première réplique, tiret à chaque changement de locuteur, guillemet fermant après la dernière.'],
      s:['Discours indirect', 'Verbes de parole et gestes de scène', 'Sous-texte', 'Exposition distillée'] },
    { n:'Discours indirect', a:'Style indirect',
      d:'Le narrateur rapporte avec ses propres mots ce que le personnage a dit, dans une proposition subordonnée (« Il dit que… », « Elle demanda si… »), avec transposition des personnes, des temps (concordance) et des repères (« demain » devient « le lendemain »).',
      u:'Résume les conversations longues ou banales et garde le contrôle au narrateur. Sert à passer vite sur ce qui ne mérite pas une scène.',
      c:'La concordance des temps est la difficulté : « Il dit qu’il viendra » / « Il dit qu’il viendrait » ne situent pas l’action de la même façon (voir la section Grammaire).',
      x:['« Il dit qu’il viendrait le lendemain, si le temps le permettait. »', 'Direct : « Je viens demain. » → Indirect : « Il annonça qu’il venait le lendemain. »'],
      s:['Discours direct', 'Discours indirect libre', 'Scène et sommaire'] },
    { n:'Discours indirect libre', a:'Style indirect libre',
      d:'Fusion de la voix du narrateur et de celle du personnage : on garde la troisième personne et les temps du passé (souvent l’imparfait), mais la phrase porte les mots, les exclamations et les doutes du personnage, sans verbe introducteur ni « que ».',
      u:'C’est l’outil central du roman moderne en focalisation interne : il donne accès à la pensée sans interrompre la narration. Pour le reconnaître : questions, exclamations, jugements et mots familiers qui ne peuvent venir que du personnage.',
      c:'Si la voix du personnage ne se distingue pas de celle du narrateur, l’effet se perd ; le lecteur doit pouvoir dire qui pense.',
      x:['« Il regarda la pendule. Minuit ! Et Charles qui ne rentrait pas. Qu’allait dire sa mère ? »', 'Flaubert en a fait l’instrument de *Madame Bovary* : les rêveries d’Emma passent par la voix du narrateur.', 'Zola dans *L’Assommoir* : la langue populaire de Gervaise envahit la narration.'],
      s:['Troisième personne limitée', 'Distance narrative', 'Monologue intérieur'] },
    { n:'Discours direct libre', a:'Paroles sans guillemets ni tirets',
      d:'Les paroles s’insèrent dans le fil de la narration sans guillemets, sans tirets et sans retour à la ligne ; parfois seuls une virgule et une majuscule marquent le changement de locuteur.',
      u:'Crée un flux oral continu, où narrateur et personnages partagent le même souffle. Fréquent chez les romanciers contemporains (Marguerite Duras, Jean Echenoz, Marie NDiaye) ; c’est aussi la signature de José Saramago.',
      c:'Chaque voix doit se distinguer par le contenu et le rythme ; le procédé demande un lecteur attentif et une grande netteté des répliques.',
      x:['« Il demanda, Tu viens avec moi, et elle répondit, Oui, mais pas aujourd’hui, Alors quand, Quand je n’aurai plus peur. »', '*L’Aveuglement* (Saramago) ; les dialogues fondus dans la phrase chez Duras.'],
      s:['Discours direct', 'Ponctuation et effets de style', 'Phrase longue'] },
    { n:'Verbes de parole et gestes de scène', a:'Verbes introducteurs · incises',
      d:'Les petites indications qui accompagnent une réplique : qui parle (« dit-il », « demanda-t-elle ») et ce qu’il fait en parlant (« Elle reposa sa tasse. »). En français, l’incise impose l’inversion du sujet : « dit-il », jamais « il dit » au milieu d’une réplique.',
      u:'« Dit » est presque invisible. Gardez les verbes expressifs (grogna, supplia, siffla) pour les cas où la réplique ne montre pas d’elle-même le ton. Un geste à la place du verbe identifie le locuteur, donne un corps à la scène et peut démentir les mots. Dans un échange rapide à deux, supprimez tout.',
      c:'L’adverbe qui explique ce que la réplique dit déjà (« — Je te hais ! hurla-t-elle furieusement ») est redondant. On ne « sourit » pas une phrase : « sourit-il » en incise est accepté par l’usage moderne, mais l’abus de verbes non déclaratifs (« soupira-t-il », « rougit-elle ») fait daté. Évitez l’incise avec pronom non inversé (« il dit ») et le faux pas « qu’il dit », familier.',
      x:['Lourd : « — Je n’irai pas, rétorqua-t-il obstinément. »', 'Léger : « — Je n’irai pas. » Il se rassit et déplia son journal.', 'Elmore Leonard, dans ses dix règles d’écriture : ne jamais utiliser d’autre verbe que « dit ».'],
      s:['Discours direct', 'Sous-texte', 'Verbes forts', 'Montrer plutôt que dire'] },
    { n:'Tutoiement et vouvoiement', a:'Formes d’adresse · tu, vous, Monsieur, Madame',
      d:'La manière dont les personnages s’adressent les uns aux autres. Le français oppose « tu » (intimité, familiarité, ou supériorité) et « vous » (respect, distance, politesse), auxquels s’ajoutent les titres (« Monsieur le Directeur », « Maître », « Docteur ») et le choix entre prénom et nom. Au Québec, le tutoiement est plus répandu et plus rapide qu’en France ; en Belgique et en Suisse, l’usage est proche de celui de la France.',
      u:'Chaque couple de personnages a sa forme d’adresse, qui dit tout de l’âge, de la classe, de l’affection et du pouvoir. Les moments où elle change sont des scènes : le premier tutoiement, le retour glacial au « vous » après une dispute, le vouvoiement entre époux de la grande bourgeoisie, l’enfant qui vouvoie ses parents dans un roman du XIXe siècle.',
      c:'Les incohérences se remarquent aussitôt. Pour un roman historique, vérifiez l’usage de l’époque et du milieu (le tutoiement révolutionnaire imposé en l’an II, le vouvoiement des domestiques, etc.).',
      x:['Asymétrie : le patron tutoie la bonne ; elle répond « Monsieur ».', 'Bascule : « — On pourrait se tutoyer, non ? — Je n’y arriverai pas, Monsieur. »', 'Dans *Le Rouge et le Noir*, le passage du « vous » au « tu » entre Julien et Mme de Rênal ou Mathilde marque chaque étape de la conquête.'],
      t:'Notez, dans une Note associée à deux Personnages, comment ils s’adressent l’un à l’autre — et à partir de quelle Scène cela change.',
      s:['Registres de langue', 'Idiolecte et marques d’oralité', 'Sous-texte', 'Bible de série'] }
  ]},
  { name:'Phrase et rythme', items:[
    { n:'Rythme de la phrase', d:'La musique de la prose : l’alternance des phrases courtes et longues, des groupes rythmiques, des pauses et des accélérations. En français, l’accent tombe en fin de groupe de mots : le rythme se compte donc par groupes, et la fin de phrase porte le poids.',
      u:'Faites épouser la forme au contenu : phrases courtes pour l’action, le choc, la certitude ; longues pour la contemplation, l’hésitation, l’accumulation. C’est la variation qui crée la musique — après trois phrases longues, une phrase brève frappe comme un tambour. Lisez toujours à voix haute (Flaubert passait ses phrases au « gueuloir »).',
      x:['« Il attendit. Rien. Il attendit encore un peu, à compter les gouttes qui tombaient de la gouttière dans le seau, et quand il fut convaincu que personne ne viendrait, il entendit, très loin, le portail. »'],
      s:['Phrase courte', 'Phrase longue', 'Cadence majeure et mineure', 'Rythme narratif'] },
    { n:'Phrase courte', a:'Style sec · minimalisme',
      d:'Phrases brèves, de syntaxe simple, avec peu de subordonnées et peu d’adjectifs.',
      u:'Tension, action, froideur, choc. L’essentiel va en fin de phrase. C’est le style de Camus dans *L’Étranger*, de Simenon, d’Hemingway, de Raymond Carver, du roman noir.',
      c:'Toujours identique, elle devient télégraphique et monotone.',
      x:['« Aujourd’hui, maman est morte » (Camus, *L’Étranger*).', '« Il ouvrit la porte. La chambre était vide. Le lit, fait. »'],
      s:['Phrase longue', 'Parataxe et hypotaxe', 'Phrase nominale', 'Théorie de l’iceberg', 'Minimalisme', 'Style sobre'] },
    { n:'Phrase longue', a:'Période · phrase-fleuve',
      d:'Phrases étendues, faites de propositions enchaînées, d’incises et de reprises, qui peuvent couvrir une page.',
      u:'Imite la pensée, la mémoire, le vertige, l’oralité torrentielle. Donnez-lui une colonne vertébrale (un verbe principal clair, ou un « et » qui la tire en avant) et des points d’appui pour que le lecteur respire.',
      c:'Sans architecture, le lecteur se perd — et ne revient pas en arrière pour se retrouver.',
      x:['Proust, *À la recherche du temps perdu* : des phrases de plus d’une page, toujours construites.', 'Claude Simon (*La Route des Flandres*) ; Mathias Énard (*Zone*, roman d’une seule phrase).', 'García Márquez, *L’Automne du patriarche* : des chapitres presque sans points.'],
      s:['Phrase courte', 'Flux de conscience', 'Discours direct libre', 'Période et phrase cumulative', 'Style lyrique'] },
    { n:'Parataxe et hypotaxe', a:'Juxtaposition, coordination et subordination',
      d:'Parataxe : propositions posées côte à côte, juxtaposées ou coordonnées, sans hiérarchie (« Il arriva, s’assit, commanda du vin »). Hypotaxe : propositions subordonnées les unes aux autres, qui explicitent la cause, le temps, la condition, la concession (« Comme il était en retard, il s’assit sans demander la permission, bien qu’il sût… »).',
      u:'La parataxe montre et laisse au lecteur le travail de relier : elle est objective, rapide, cinématographique. L’hypotaxe explique et analyse : c’est le style du raisonnement et de la psychologie.',
      x:['Parataxe : Camus, Hemingway, Cormac McCarthy, la Bible.', 'Hypotaxe : Proust, Henry James, les grands portraits de Balzac.'],
      s:['Asyndète', 'Polysyndète', 'Phrase courte', 'Phrase longue'] },
    { n:'Phrase nominale', d:'Phrase sans verbe conjugué, construite autour d’un nom.',
      u:'Fixe une image comme une photographie ou une didascalie : bonne pour ouvrir une scène, pour les énumérations descriptives et pour le choc. Les Goncourt et les naturalistes en ont fait une marque d’« écriture artiste ».',
      c:'En série, elle donne un style de notes ou de script.',
      x:['« La nuit. Une pluie fine. Personne dans la rue. »', '« Un coup de feu. Puis le silence. »'],
      s:['Phrase courte', 'Ellipse (figure)', 'Impressionnisme littéraire'] },
    { n:'Rythme ternaire', a:'Tricolon · règle de trois',
      d:'Séries de trois éléments — mots, groupes, propositions ou événements. Deux éléments créent un motif ; le troisième le confirme ou le brise. Le rythme ternaire est un pilier de la prose et de l’éloquence françaises.',
      u:'Dans la phrase : trois adjectifs, trois verbes, le plus fort à la fin. Dans l’humour : deux éléments normaux et un inattendu. Dans l’intrigue : trois tentatives, trois épreuves, trois frères — la structure des contes.',
      x:['« Liberté, Égalité, Fraternité. »', '« Je suis venu, j’ai vu, j’ai vaincu. »', 'Humour : « Il avait tout prévu : la tente, la lampe et un avocat. »', 'Intrigue : les trois petits cochons ; les trois visites des esprits dans *Un chant de Noël*.'],
      s:['Gradation', 'Anaphore', 'Cadence majeure et mineure', 'Tentatives et échecs'] },
    { n:'Cadence majeure et mineure', a:'Clausule · chute de phrase',
      d:'Notion de la stylistique française : une phrase en cadence majeure a des membres de longueur croissante (le dernier est le plus long), ce qui donne ampleur et équilibre ; en cadence mineure, le dernier membre est plus court, ce qui produit une chute sèche, abrupte ou ironique. La clausule est la fin rythmique de la phrase.',
      u:'Pour une phrase solennelle, lyrique ou conclusive, allongez progressivement les membres. Pour une chute, une pointe, un coup, terminez court. Alterner les deux évite la monotonie oratoire.',
      c:'Toutes les phrases en cadence majeure font sermon ; toutes en cadence mineure font tic de chroniqueur.',
      x:['Majeure : « Il aimait la mer, les ports au petit matin et le bruit des drisses contre les mâts quand le vent se lève. »', 'Mineure : « Il avait promis la mer, les îles, une vie nouvelle. Ils eurent Dieppe. »', 'Les oraisons funèbres de Bossuet, modèles de cadence majeure.'],
      s:['Rythme de la phrase', 'Place forte de la phrase', 'Gradation', 'Rythme ternaire'] },
    { n:'Place forte de la phrase', a:'Mise en relief · fin de phrase',
      d:'Dans une phrase, la place la plus forte est la fin ; la deuxième, le début. Le milieu est la zone d’ombre. Il en va de même pour le paragraphe et le chapitre. Le français dispose aussi de tournures de mise en relief : « c’est… qui / que », la dislocation (« Ce livre, je l’ai lu »).',
      u:'Placez à la fin le mot ou l’information qui doit résonner ; cachez au milieu le secondaire (ou l’indice que vous ne voulez pas faire remarquer). En révision, regardez le dernier mot de chaque paragraphe : c’est celui qui reste.',
      c:'L’abus de « c’est… qui » alourdit ; mieux vaut souvent réordonner la phrase.',
      x:['Faible : « On retrouva son corps dans la rivière, trois jours plus tard, d’après la police. »', 'Fort : « Trois jours plus tard, d’après la police, on la retrouva dans la rivière. »', 'Indice caché : « Il portait son manteau habituel, un journal plié, des gants de cuir et l’air de quelqu’un qui a mal dormi. »'],
      s:['Rythme de la phrase', 'Période et phrase cumulative', 'Gradation', 'Inversion', 'Préfiguration'] },
    { n:'Période et phrase cumulative', a:'Phrase périodique · phrase à rallonges',
      d:'Dans la période (phrase périodique), la proposition principale — et avec elle le sens — n’arrive qu’à la fin, après une série d’éléments qui la retardent ; elle a une montée (protase) et une descente (apodose). Dans la phrase cumulative, la principale vient d’abord et l’on y ajoute des détails, comme quand on regarde de plus en plus près.',
      u:'La période crée suspension et solennité : le lecteur attend le verbe. La phrase cumulative est naturelle et exploratoire, elle ressemble à une pensée en train de se faire, et convient pour décrire en mouvement.',
      c:'Des périodes les unes après les autres sonnent comme un discours de tribune.',
      x:['Période : « Après trente ans de lettres retournées, de téléphones raccrochés et de Noëls silencieux, son père sonna à la porte. »', 'Cumulative : « Son père sonna à la porte, plus petit que dans son souvenir, le chapeau à la main, les yeux sur ses chaussures. »'],
      s:['Phrase longue', 'Place forte de la phrase', 'Inversion', 'Parataxe et hypotaxe'] },
    { n:'Voix active et voix passive', d:'À l’actif, le sujet fait l’action (« Marthe a cassé le vase ») ; au passif, il la subit (« Le vase a été cassé »). Le passif permet de taire l’agent ; le « on » et la tournure pronominale aussi (« Le vase s’est cassé »).',
      u:'L’actif est plus direct et plus vivant : c’est le choix par défaut. Le passif sert quand l’agent est inconnu, quand on veut mettre la victime au premier plan — ou quand quelqu’un veut fuir sa responsabilité, ce qui en fait un excellent outil pour caractériser politiciens, bureaucrates et coupables.',
      x:['Actif : « Le gardien ouvrit la cellule. »', 'Passif qui dissimule : « Des erreurs ont été commises. »', 'Pronominal évasif : « — Il s’est cassé tout seul, maman. »'],
      s:['Verbes forts', 'Euphémisme', 'Registres de langue'] },
    { n:'Incise et aparté', a:'Parenthèse · proposition incise',
      d:'Élément inséré au milieu de la phrase, entre virgules, tirets ou parenthèses, qui l’interrompt pour ajouter, corriger ou commenter.',
      u:'Entre virgules, l’incise s’intègre ; entre tirets, elle se détache ; entre parenthèses, elle baisse la voix — c’est le lieu de l’aparté complice, de l’ironie et de ce que le narrateur feint de croire sans importance.',
      c:'Les incises longues éloignent le sujet du verbe et obligent à relire.',
      x:['« La tante Amélie — qui n’avait jamais quitté Vierzon — nous expliqua Paris. »', '« Ils se marièrent en mai (lui disait juin, mais il disait beaucoup de choses). »', 'Nabokov, dans *Lolita*, expédie la mort de la mère de Humbert en deux mots entre parenthèses : « (pique-nique, foudre) ».'],
      s:['Ponctuation et effets de style', 'Narrateur intrusif (commentateur)', 'Ironie'] },
    { n:'Ponctuation et effets de style', a:'Ponctuation expressive',
      d:'L’usage de la ponctuation comme ressource de style, et pas seulement de grammaire : points de suspension, tirets, deux-points, parenthèses, absence de virgules, points qui coupent la phrase.',
      u:'Le tiret interrompt et détache ; les deux-points promettent une révélation ; la parenthèse crée un aparté ; le point au milieu d’une phrase frappe (« Non. Je. Pars. »). Les règles et les espaces typographiques français sont détaillés dans la section Ponctuation.',
      c:'Le point d’exclamation s’use vite : un par page, c’est beaucoup. Majuscules et italiques pour crier sont des béquilles.',
      x:['Céline : les points de suspension comme « rails » de l’émotion dans *Mort à crédit*.', 'Apollinaire supprime toute ponctuation dans *Alcools* (1913).', 'Saramago : seulement virgules et points, une majuscule pour chaque réplique.'],
      s:['Discours direct libre', 'Aposiopèse', 'Rythme de la phrase'] },
    { n:'Répétition et refrain', a:'Leitmotiv verbal',
      d:'Reprise délibérée d’un mot, d’une phrase ou d’une formule tout au long du texte.',
      u:'Crée cohésion, obsession et rythme. Une phrase qui revient dans des contextes différents change de sens à chaque fois — et peut clore le livre avec un autre poids.',
      c:'À distinguer de la répétition par négligence : la répétition voulue doit se remarquer comme un choix.',
      x:['« Ainsi va la vie » — la formule résignée qui suit chaque mort dans *Abattoir 5* (Vonnegut).', '« Jamais plus », le refrain du *Corbeau* (Poe, traduit par Baudelaire et Mallarmé).', '« Je préférerais ne pas » — la réponse de *Bartleby* (Melville).'],
      s:['Motif récurrent', 'Anaphore', 'Répétition et synonymes'] },
    { n:'Paragraphe et blanc typographique', d:'Le découpage en paragraphes, les lignes blanches et les coupures de section sont aussi une ponctuation, à plus grande échelle.',
      u:'Un paragraphe d’une seule ligne détache. Une ligne blanche marque un saut de temps, de lieu ou de point de vue. Les blocs compacts donnent densité et claustrophobie ; beaucoup de blanc donne vitesse et respiration.',
      x:['Un chapitre d’une seule phrase : « Ma mère est un poisson », dans *Tandis que j’agonise* (Faulkner).', 'Les blocs sans alinéa de Thomas Bernhard ; les fragments de Pascal Quignard.'],
      s:['Ellipse narrative', 'Rythme narratif', 'Procédés typographiques', 'Chapitres courts et cliffhangers'] },
    { n:'Euphonie et cacophonie', a:'Hiatus · cacophonie · écho',
      d:'L’euphonie est l’enchaînement de sons agréable à l’oreille ; la cacophonie, l’enchaînement désagréable. Les défauts les plus courants en prose : le hiatus (voyelles qui se heurtent : « il alla à Arras »), la cacophonie proprement dite (sons qui se répètent : « ton thé t’a-t-il ôté ta toux ? ») et l’écho (rime involontaire).',
      u:'Lisez à voix haute : c’est la seule façon de les repérer. Les mêmes sons, fautifs par négligence, deviennent une ressource quand ils sont choisis — une phrase rocailleuse pour une scène âpre.',
      c:'Écho classique des débutants : « -tion » et « -ment » en série (« La réaction de la population à l’inondation fut l’indignation » ; « Il entra lentement et s’assit silencieusement »).',
      x:['Hiatus : « Il alla à Arras. »', 'Écho : « Sa décision provoqua l’admiration de la direction. »', 'Cacophonie : « Qu’a-t-il cassé ? » / « Non, il n’y en a ni ici ni là. »'],
      s:['Allitération', 'Assonance', 'Rythme de la phrase'] },
    { n:'Prose poétique', a:'Poème en prose · prose lyrique',
      d:'Prose qui emprunte les moyens de la poésie — rythme marqué, images denses, répétitions, suspension du récit — sans le vers. Le poème en prose est un genre que la France a illustré tout particulièrement.',
      u:'Sert les moments de contemplation, d’extase, de deuil ou de délire, où l’état compte plus que l’action. Dans un roman, c’est un changement de tempo : quelques lignes, un paragraphe, un chapitre bref.',
      c:'Prolongée, elle lasse et freine l’intrigue ; la « prose violette » (ornée sans nécessité) est son échec.',
      x:['*Gaspard de la Nuit* (Aloysius Bertrand), le modèle revendiqué par Baudelaire.', '*Le Spleen de Paris* (Baudelaire) ; *Les Illuminations* (Rimbaud).', '*Les Nourritures terrestres* (Gide) ; *Les Vagues* (Virginia Woolf).'],
      s:['Rythme de la phrase', 'Images sensorielles', 'Pause descriptive', 'Maximalisme', 'Style lyrique'] }
  ]},
  { name:'Mots et registres', items:[
    { n:'Registres de langue', a:'Niveaux de langue : soutenu, courant, familier, populaire, argotique',
      d:'La variété de langue adaptée à une situation : soutenu (ou littéraire), courant, familier, populaire, argotique, à quoi s’ajoutent les langues de métier. À ne pas confondre avec les registres littéraires (comique, tragique, lyrique…).',
      u:'Le registre caractérise le personnage (âge, classe, région, métier) et la relation entre ceux qui parlent : un glissement de registre au milieu d’une scène révèle un changement de pouvoir ou d’émotion. La narration peut garder un registre courant tandis que les dialogues descendent dans le familier.',
      c:'L’argot vieillit vite ; le registre familier en dose massive ne choque plus. La négation sans « ne » (« je sais pas ») suffit souvent à rendre l’oral, sans tout transcrire.',
      x:['Soutenu : « Veuillez avoir l’obligeance de patienter. »', 'Courant : « Attendez un instant, s’il vous plaît. »', 'Familier : « Attends deux secondes. »', 'Argotique : « Bouge pas, j’arrive. »', '*Zazie dans le métro* (Queneau) : « Doukipudonktan », l’oral écrit tel qu’il sonne.'],
      s:['Ton', 'Idiolecte et marques d’oralité', 'Voix narrative', 'Dysphémisme', 'Registres littéraires'] },
    { n:'Ton', d:'L’attitude du narrateur (ou du texte) envers ce qu’il raconte et envers le lecteur : grave, ironique, tendre, cynique, neutre, comique, élégiaque, épique.',
      u:'Le ton est un contrat : il s’établit dès la première page et dit au lecteur comment lire la suite. Il peut contraster avec le contenu — l’horreur racontée avec légèreté, la banalité racontée avec solennité —, et ce décalage est l’un des effets les plus forts qui soient.',
      c:'Les ruptures de ton involontaires (une plaisanterie au mauvais moment) détruisent la confiance du lecteur.',
      x:['L’horreur sur un ton neutre : *La Métamorphose* (Kafka) — se réveiller en insecte et s’inquiéter de son travail.', 'La tragédie sur un ton comique : *Candide* (Voltaire) ; *Catch-22* (Joseph Heller).', 'Le banal sur un ton épique : *Ulysse* (Joyce).'],
      s:['Ironie', 'Voix narrative', 'Atmosphère', 'Registres littéraires'] },
    { n:'Choix lexical', a:'Le mot juste (Flaubert)',
      d:'La sélection des mots : concrets ou abstraits, précis ou génériques, simples ou rares, populaires ou savants.',
      u:'Le concret et le précis font voir : non pas « un arbre » mais « un platane », non pas « une voiture » mais « une 2 CV jaune ». Les noms exacts donnent de l’autorité au narrateur. Puisez le vocabulaire dans le monde du Personnage POV.',
      c:'Le mot rare ne vaut que s’il est le mot juste ; sinon c’est de l’étalage. Méfiez-vous aussi des mots passe-partout : « chose », « faire », « mettre », « il y a », « être ».',
      x:['Générique : « Il mangea quelque chose et sortit. »', 'Précis : « Il avala debout la moitié d’un jambon-beurre froid et sortit. »'],
      s:['Verbes forts', 'Détail révélateur', 'Champ lexical'] },
    { n:'Verbes forts', a:'Économie d’adverbes et d’adjectifs',
      d:'Préférer le verbe précis au verbe général flanqué d’un adverbe, et le nom exact au nom vague accompagné d’un adjectif.',
      u:'« Il se traîna » plutôt que « il marcha lentement » ; « elle chuchota » plutôt que « elle dit tout bas » ; « une masure » plutôt que « une petite maison pauvre ». En révision, traquez les adverbes en « -ment » et les « faire », « mettre », « il y a » : le verbe pourrait-il faire le travail seul ?',
      c:'Ce n’est pas une interdiction : l’adjectif inattendu et l’adverbe qui contredit le verbe (« il sourit férocement ») valent de l’or.',
      x:['Faible : « Il ferma la porte très fort. » → Fort : « Il claqua la porte. »', 'Faible : « Elle le regarda fixement. » → Fort : « Elle le dévisagea. »'],
      s:['Choix lexical', 'Adjectif expressif', 'Montrer plutôt que dire'] },
    { n:'Adjectif expressif', a:'Place de l’adjectif · double et triple adjectivation',
      d:'L’adjectif comme ressource de style : en paires ou en triades, avant ou après le nom, mêlant le physique et le moral. En français, la place de l’adjectif change souvent le sens : antéposé, il est plutôt subjectif ou figuré ; postposé, objectif ou littéral.',
      u:'Jouez sur la place : « un grand homme » / « un homme grand », « un pauvre type » / « un type pauvre », « un ancien château » / « un château ancien », « sa propre chemise » / « sa chemise propre ». Associez un adjectif concret et un adjectif abstrait (« une lumière douce et triste ») ou déplacez-le (hypallage).',
      c:'Deux adjectifs synonymes valent moins qu’un seul ; l’adjectif « de remplissage » (« un silence pesant », « une nuit noire ») est un cliché.',
      x:['« Un brave homme » / « un homme brave » ; « un curieux personnage » / « un personnage curieux ».', 'Les triades d’adjectifs de Flaubert, qu’il pesait au gueuloir.'],
      s:['Hypallage', 'Verbes forts', 'Synesthésie'] },
    { n:'Champ lexical', a:'Isotopie · réseau d’images',
      d:'Ensemble des mots qui se rapportent à un même domaine (la mer, la guerre, la maladie, la religion), répartis dans un texte.',
      u:'Un champ lexical discret et cohérent crée l’unité et le sous-texte : décrire un repas de famille avec le vocabulaire de la bataille dit tout sans rien dire.',
      x:['« La mère attaqua le rôti, prit l’oncle à revers et conquit la dernière pomme de terre. »', 'Le vocabulaire de la machine et de l’animal autour de la mine du Voreux dans *Germinal* (Zola).'],
      s:['Métaphore filée', 'Motif récurrent', 'Sous-texte'] },
    { n:'Idiolecte et marques d’oralité', a:'Parler propre · tic de langage',
      d:'La façon de parler propre à chaque personnage : vocabulaire, tics, syntaxe, prononciation suggérée, ce qu’il ne dit jamais.',
      u:'Test : en cachant les noms, sait-on qui parle ? Distinguez par le rythme et les choix de mots plus que par l’orthographe. Un tic ou une expression fétiche suffit, s’il est employé avec parcimonie. Marques d’oralité utiles en français : chute du « ne » de négation, « on » pour « nous », dislocations (« Moi, mon frère, il… »), « ben », « hein », « quoi » en fin de phrase.',
      c:'La transcription phonétique lourde (« j’sais pas c’qu’y veut ») fatigue et peut sembler moqueuse. Suggérez, ne transcrivez pas.',
      x:['Monsieur Homais (*Madame Bovary*) et ses phrases toutes faites de pharmacien progressiste.', 'Sancho Pança et ses proverbes en cascade.', 'Les « Mille sabords ! » et autres jurons du capitaine Haddock (Hergé).'],
      s:['Registres de langue', 'Régionalisme', 'Anacoluthe', 'Style oral (skaz)', 'Caractérisation directe et indirecte'] },
    { n:'Archaïsme', d:'Mot, forme ou construction tombés en désuétude.',
      u:'Donne une couleur d’époque au roman historique et à la fantasy, ou de la solennité. Dosez : une cadence ancienne et quelques mots-clés suffisent à créer l’illusion — le lecteur veut croire à l’époque, pas la déchiffrer. Voir la section Français d’autrefois.',
      c:'Gare aux anachronismes de vocabulaire : un personnage du XVIe siècle ne « stresse » pas et ne « gère » pas ses émotions. Et l’archaïsme approximatif (« Oyez, gente damoiselle ! ») tourne vite au pastiche involontaire.',
      x:['« Moult », « occire », « ouïr », « icelle », « nonobstant », « s’ensauver ».', 'Les *Contes drolatiques* de Balzac, écrits dans un français pseudo-rabelaisien.', '*L’Œuvre au noir* (Marguerite Yourcenar) : syntaxe et lexique à la saveur du XVIe siècle, sans cesser d’être lisible.'],
      s:['Néologisme', 'Inversion', 'Pastiche et parodie', 'Roman historique'] },
    { n:'Néologisme', d:'Mot nouveau, créé par l’auteur par dérivation, composition, mot-valise ou emprunt.',
      u:'Nomme ce qui n’a pas de nom : les réalités des mondes inventés, des sensations, la langue d’un enfant. Fonctionne quand on le comprend du premier coup par le contexte ou par sa formation.',
      x:['Rabelais, grand inventeur de mots (« agélaste », celui qui ne rit pas).', 'Boris Vian dans *L’Écume des jours* : le « pianocktail ».', 'Orwell, *1984* : « novlangue », « doublepensée ».', 'Henri Michaux : « Il l’emparouille et l’endosque contre terre » (*Le Grand Combat*).'],
      s:['Archaïsme', 'Emprunt et anglicisme', 'Construction d’univers'] },
    { n:'Régionalisme', a:'Belgicisme · helvétisme · québécisme',
      d:'Mot ou expression propre à une région ou à un pays de la francophonie.',
      u:'Enracine l’histoire dans un lieu et donne de l’authenticité aux dialogues. Préférez les termes qui se comprennent par le contexte et évitez le glossaire. Exemples : en Belgique et en Suisse, « septante », « nonante » (et « huitante » dans certains cantons suisses) ; en Belgique, « une drache » (averse), « savoir » pour « pouvoir » ; en Suisse, « une panosse » (serpillière), « un natel » ; au Québec, « magasiner », « blonde » (petite amie), « char » (voiture), « dépanneur ».',
      c:'Vérifiez auprès de locuteurs ; le pittoresque de carte postale est condescendant. Attention aux faux amis entre pays (« déjeuner » désigne le petit-déjeuner en Belgique, en Suisse et au Québec).',
      x:['Giono et la Provence ; Ramuz et le pays de Vaud ; Simenon et Liège.', '*Les Belles-Sœurs* (Michel Tremblay) : le joual montréalais sur scène.', '*Les Soleils des indépendances* (Ahmadou Kourouma) : un français malinkisé ; *Texaco* (Patrick Chamoiseau) et la créolité.'],
      s:['Idiolecte et marques d’oralité', 'Registres de langue', 'Emprunt et anglicisme'] },
    { n:'Emprunt et anglicisme', a:'Xénisme · mot étranger · alternance de langues',
      d:'Mot ou expression d’une autre langue employés dans le texte. On parle de xénisme tant que le mot est senti comme étranger (en italique), d’emprunt quand il est intégré à la langue.',
      u:'Caractérise un milieu (l’anglais des start-up, l’italien des salons du XVIIIe siècle), un personnage émigré ou snob, et crée une couleur locale. Mettez en italique les mots non francisés.',
      c:'Au Québec, la lutte contre les anglicismes est plus vive qu’en France (« courriel » plutôt que « mail », « fin de semaine » plutôt que « week-end », « clavardage ») : un personnage québécois qui dit « faire du shopping » sonnera faux, et un Parisien qui dit « magasiner » aussi.',
      x:['Proust se moque de l’anglomanie d’Odette de Crécy, qui parsème ses phrases de mots anglais.', 'Le franglais satirisé par Étiemble dans *Parlez-vous franglais ?* (1964).'],
      s:['Néologisme', 'Registres de langue', 'Régionalisme'] },
    { n:'Cliché', a:'Lieu commun · expression toute faite · poncif',
      d:'Expression ou image tant employée qu’elle a perdu son effet (« un silence de mort », « le cœur battant la chamade », « un frisson lui parcourut l’échine »).',
      u:'Dans la narration, remplacez-le par le détail concret et précis. Dans le dialogue, au contraire, il est utile : les gens parlent par formules, et le cliché caractérise. On peut aussi le détourner en le prenant au pied de la lettre ou en tordant sa fin.',
      x:['Usé : « Elle devint blanche comme un linge. »', 'Renouvelé : « Elle prit la couleur du mur — et le mur était vert hôpital. »', 'Flaubert les a collectionnés dans le *Dictionnaire des idées reçues*.'],
      s:['Comparaison', 'Catachrèse', 'Proverbes et expressions idiomatiques', 'Défamiliarisation'] },
    { n:'Dénotation et connotation', d:'La dénotation est le sens littéral d’un mot, celui du dictionnaire ; la connotation, le halo d’associations, d’affects et de jugements qu’il porte avec lui. « Maison », « foyer », « demeure », « domicile », « bicoque » et « taudis » peuvent désigner le même lieu.',
      u:'Entre synonymes, choisissez par la connotation : c’est elle qui donne le ton et le point de vue. Le mot qu’un personnage emploie pour une chose dit ce qu’il en pense — « mon mari », « mon homme », « le père de mes enfants », « ce monsieur ».',
      x:['« Mince » / « svelte » / « maigre » / « décharné ».', '« Têtu » / « persévérant » / « buté ».', '« Il est mort » / « il est décédé » / « il nous a quittés » / « il a clamsé ».'],
      s:['Choix lexical', 'Ton', 'Euphémisme', 'Dysphémisme'] },
    { n:'Ambiguïté', a:'Polysémie · double sens',
      d:'Possibilité pour un mot, une phrase ou une situation d’avoir plus d’une lecture. Elle peut être lexicale (un mot à plusieurs sens) ou syntaxique (une phrase à deux analyses possibles).',
      u:'L’ambiguïté voulue est une ressource : prophéties qui se réalisent de façon inattendue, répliques qu’on ne comprend qu’à la relecture, fins ouvertes. L’ambiguïté involontaire est un défaut à éliminer en révision — en français, gare aux possessifs et aux pronoms « il », « le », « son ».',
      x:['Involontaire : « Il a vu l’homme avec les jumelles. » (qui tient les jumelles ?)', 'Involontaire : « Paul a dit à Marc que sa voiture avait été volée. » (la voiture de qui ?)', 'Voulue : la prophétie des sorcières dans *Macbeth* — nul homme « né d’une femme » ne pourra lui nuire.', 'Fin ambiguë : *Le Tour d’écrou* (Henry James) — fantômes ou folie ?'],
      s:['Jeu de mots', 'Narrateur non fiable', 'Préfiguration', 'Coup de théâtre'] },
    { n:'Diminutifs et suffixes expressifs', a:'Hypocoristiques · suffixes péjoratifs',
      d:'Le français a moins de diminutifs vivants que l’espagnol, l’italien ou le portugais, mais ses suffixes restent expressifs : diminutifs et affectueux (-et, -ette, -ot, -on : fillette, maisonnette, frérot, chaton), redoublements hypocoristiques (Mimi, Loulou, Fifi, dodo), et surtout péjoratifs (-ard : chauffard, vantard ; -asse : paperasse, vinasse, blondasse ; -âtre : bellâtre, douceâtre, rougeâtre ; -aud : lourdaud ; -ailler, -oter : criailler, toussoter).',
      u:'Les suffixes péjoratifs donnent en un mot le mépris d’un personnage ou d’un narrateur (« un écrivaillon », « une politicaillerie »). Les hypocoristiques disent la tendresse, l’enfance, le couple — ou l’infantilisation. « Petit » antéposé joue souvent le rôle du diminutif : « un petit café ? », « ma petite dame ».',
      c:'Les hypocoristiques en excès rendent la narration mièvre ; un suffixe péjoratif dans la bouche du narrateur engage son jugement.',
      x:['« Un écrivaillon de province qui se prenait pour Balzac. »', '« Elle l’appelait Loulou devant les autres, Louis quand elle était fâchée. »', '« Un petit verre ? » — le diminutif de politesse.'],
      s:['Idiolecte et marques d’oralité', 'Ton', 'Ironie', 'Dénotation et connotation'] },
    { n:'Proverbes et expressions idiomatiques', a:'Locutions figées',
      d:'Proverbe : sentence populaire de sagesse pratique (« Qui trop embrasse mal étreint »). Expression idiomatique : groupe de mots dont le sens ne se déduit pas des parties (« poser un lapin », « tomber dans les pommes », « avoir le cafard », « coûter les yeux de la tête »).',
      u:'Donnent une saveur populaire et ancrent un personnage dans une génération et une région. On peut les tordre pour surprendre ou les prendre au pied de la lettre pour faire rire. Un proverbe fait aussi un bon titre ou une bonne épigraphe (Musset a écrit des « proverbes » dramatiques : *On ne badine pas avec l’amour*).',
      c:'Presque toujours intraduisibles, et variables d’un pays à l’autre : au Québec, « avoir les deux pieds dans la même bottine » n’a pas d’équivalent exact en France.',
      x:['Sancho Pança, qui parle par proverbes au désespoir de don Quichotte.', 'Les proverbes détournés de San-Antonio et de Frédéric Dard.', 'Détourné : « Un tiens vaut mieux que deux tu l’auras — surtout quand le deuxième est un huissier. »'],
      s:['Cliché', 'Idiolecte et marques d’oralité', 'Régionalisme', 'Catachrèse'] },
    { n:'Jurons et grossièretés', a:'Gros mots · sacres québécois',
      d:'Le vocabulaire grossier ou tabou : jurons, injures, obscénités — et leurs substituts gênés (« punaise », « mince », « zut », « purée »). Le français de France jure surtout par le sexe et l’excrément ; le Québec par le vocabulaire religieux (les « sacres » : tabarnak, câlice, ostie, et leurs formes atténuées « tabarouette », « câline »).',
      u:'Le juron vaut par le contraste : chez un personnage qui n’en dit jamais, un seul fait trembler la page. Qui jure, comment, et devant qui, caractérise plus que le juron lui-même. Dans les mondes inventés, créer des jurons propres est un moyen économique de montrer ce qui y est sacré.',
      c:'À dose continue, il anesthésie. Pensez aussi au lecteur et à la collection visée.',
      x:['Le « Mot de Cambronne » à Waterloo, que Hugo raconte longuement dans *Les Misérables*.', 'Les injures inventives du capitaine Haddock : « Bachi-bouzouk ! », « Ectoplasme ! ».', 'Jurons inventés : « Par la barbe de Merlin ! »'],
      s:['Registres de langue', 'Dysphémisme', 'Construction d’univers', 'Idiolecte et marques d’oralité'] },
    { n:'Argot et jargon', a:'Langue de groupe · technolecte · verlan',
      d:'Argot : vocabulaire propre à un groupe (à l’origine la pègre, puis les lycéens, les soldats, les cités ; le verlan — « meuf », « relou », « vénère » — en est une forme). Jargon : vocabulaire technique d’un métier ou d’une science.',
      u:'Deux ou trois mots exacts du métier suffisent pour qu’on croie que le personnage est vraiment médecin, marin ou policier. Le contexte doit suffire à comprendre ; le nouveau venu qui pose des questions fait le reste.',
      c:'Un argot mal maîtrisé sonne faux immédiatement — renseignez-vous. Et il date : celui de 1995 date le livre de 1995.',
      x:['Le vocabulaire maritime de *Moby Dick* et de Patrick O’Brian.', 'Le jargon hospitalier : « On a un polytrauma qui arrive, préparez le bloc. »', 'L’argot du milieu chez Albert Simonin (*Touchez pas au grisbi !*) et dans les dialogues d’Audiard.'],
      s:['Registres de langue', 'Choix lexical', 'Néologisme', 'Exposition distillée'] },
    { n:'Noms des personnages', a:'Onomastique · noms parlants',
      d:'Le nom est la première caractérisation : il suggère une époque, une région, une classe, parfois un destin. Les « noms parlants » disent ouvertement ce que le personnage est.',
      u:'Vérifiez que le prénom existait à l’époque et dans le milieu. Évitez les noms proches ou à même initiale pour des personnages qui se côtoient. Surnoms, diminutifs et patronymes montrent qui parle : la même femme est « Marie-Thérèse », « Maïté », « Madame Delorme » et « la veuve ». Ne pas nommer est aussi un choix.',
      x:['Balzac : Gobseck (l’usurier qui « gobe sec »), Rastignac, Vautrin.', 'Molière : Harpagon (du latin *harpago*, crochet), Tartuffe — devenus noms communs.', 'Flaubert : Homais, Bovary (bovin) ; Proust : Swann, Charlus, Verdurin.', 'Rowling : Remus Lupin, Drago Malefoy, Sirius Black.'],
      t:'Le nom de chaque Personnage peut être changé à tout moment dans sa fiche : toutes les Scènes affichent alors le nouveau nom.',
      s:['Antonomase', 'Tutoiement et vouvoiement', 'Caractérisation directe et indirecte', 'Personnage type', 'Bible de série'] },
    { n:'Répétition et synonymes', a:'Variation élégante',
      d:'Le dilemme de la révision : répéter le même mot ou le remplacer par un synonyme. L’école française enseigne à éviter les répétitions ; la bonne prose répète quand le mot juste est unique.',
      u:'Répétez sans crainte les noms des personnages, « dit » et les termes concrets : appeler un chien, en cinq lignes, « le chien », « l’animal », « le canidé » et « le fidèle compagnon » distrait plus que la répétition. Variez en revanche les mots rares ou très marqués, qui se remarquent à la deuxième occurrence.',
      x:['Variation forcée : « Paul entra. Le jeune avocat posa sa serviette. Le Lyonnais de trente ans soupira. »', 'Répétition juste : « Paul entra. Il posa sa serviette. Il soupira. »'],
      s:['Répétition et refrain', 'Choix lexical', 'Périphrase', 'Verbes de parole et gestes de scène'] }
  ]},
  { name:'Image, description et atmosphère', items:[
    { n:'Images sensorielles', a:'Imagerie · les cinq sens',
      d:'Langage qui sollicite les sens : la vue, l’ouïe, l’odorat, le goût, le toucher — et aussi le mouvement, la température, la douleur, l’équilibre.',
      u:'La vue domine par défaut ; l’odorat et le toucher sont ceux qui accrochent le mieux la mémoire et le corps du lecteur. Deux ou trois détails sensoriels bien choisis par scène suffisent.',
      x:['La madeleine trempée dans le thé qui rend son enfance au narrateur de Proust (*Du côté de chez Swann*).', '*Le Parfum* (Patrick Süskind) : un roman entier raconté par l’odorat.', '« La pièce sentait la cire et les pommes trop mûres. »'],
      s:['Synesthésie', 'Détail révélateur', 'Montrer plutôt que dire'] },
    { n:'Détail révélateur', a:'Détail significatif · petit fait vrai (Stendhal)',
      d:'Le détail concret et inattendu qui, à lui seul, rend réel un personnage, un lieu ou une situation — et suggère tout le reste. Stendhal parlait du « petit fait vrai ».',
      u:'Au lieu du portrait complet, choisissez le trait que seule cette personne possède. Tchekhov : ne dites pas que la lune brille, montrez son reflet sur un éclat de verre.',
      c:'Une liste de détails banals (cheveux châtains, yeux marron, taille moyenne) ne fait voir personne.',
      x:['« Elle portait son alliance au bout d’une chaînette, autour du cou. »', '« Dans le frigo, de la moutarde et une bouteille de champagne. »', 'La casquette composite de Charles Bovary ; le bouquet de mariée de la première épouse, qu’Emma trouve dans la chambre en arrivant à Tostes.'],
      s:['Montrer plutôt que dire', 'Synecdoque', 'Portrait', 'Caractérisation directe et indirecte'] },
    { n:'Description', a:'Statique et dynamique',
      d:'Représentation des lieux, des objets et des personnages. La description statique suspend l’action pour peindre un tableau ; la description dynamique s’intègre à l’action et passe par le regard et les gestes de ceux qui sont là.',
      u:'Décrivez en mouvement et à travers le Personnage POV : ce qu’il remarque le révèle. Organisez le regard (du général au détail, du lointain au proche) et demandez-vous quelle émotion la description doit laisser.',
      c:'Les lecteurs sautent les blocs descriptifs qui ne changent rien à la scène. La description « balzacienne » en ouverture était un pacte de lecture de son temps, pas une obligation.',
      x:['Statique : la pension Vauquer au début du *Père Goriot* (Balzac).', 'Dynamique : « Il traversa la pièce en évitant les cartons, écarta un rideau qui lâcha sa poussière et découvrit la fenêtre clouée. »', 'Le regard d’Emma sur le château de la Vaubyessard (*Madame Bovary*) : la description devient désir.'],
      s:['Pause descriptive', 'Images sensorielles', 'Atmosphère', 'Portrait'] },
    { n:'Atmosphère', a:'Ambiance · climat',
      d:'L’impression émotionnelle dominante d’une scène ou d’un livre — oppression, mélancolie, menace, légèreté — créée par le décor, la lumière, le temps qu’il fait, les sons et le rythme des phrases.',
      u:'Sélectionnez les détails du décor qui servent l’émotion et coupez les autres. L’atmosphère peut aussi contredire l’action (un crime par une journée radieuse) pour un effet plus fort.',
      x:['Le brouillard et la boue de Londres à l’ouverture de *La Maison d’Âpre-Vent* (Dickens).', 'La nuit noire et le vent de la plaine dans l’ouverture de *Germinal* (Zola).', 'La chaleur écrasante sur la plage dans *L’Étranger* (Camus).'],
      s:['Paysage état d’âme', 'Ton', 'Description'] },
    { n:'Paysage état d’âme', a:'Nature en miroir · « pathetic fallacy » (Ruskin)',
      d:'Le paysage et le temps qu’il fait reflètent les sentiments des personnages. La formule vient d’Amiel : « Un paysage quelconque est un état de l’âme » (*Journal intime*). Les Anglais parlent de « pathetic fallacy ».',
      u:'L’orage la nuit du crime, la pluie à l’enterrement. Cela fonctionne mieux discret — ou inversé : un soleil éclatant un jour de deuil rend le deuil plus cruel.',
      c:'C’est l’un des clichés les plus usés du mélodrame.',
      x:['« Il pleure dans mon cœur / Comme il pleut sur la ville » (Verlaine, *Romances sans paroles*).', 'Les paysages romantiques de Chateaubriand (*René*) et de Lamartine (*Le Lac*).', 'La tempête qui accompagne la folie de Lear dans *Le Roi Lear*.'],
      s:['Personnification', 'Atmosphère', 'Corrélatif objectif'] },
    { n:'Corrélatif objectif', a:'T. S. Eliot',
      d:'Un objet, une situation ou un enchaînement d’événements qui sert de formule à une émotion : au lieu de nommer le sentiment, on présente la chose concrète qui le fera naître chez le lecteur.',
      u:'Demandez-vous : quel objet, quel geste, quelle image contient cette émotion ? Le deuil peut être un manteau qui garde l’odeur de quelqu’un ; la solitude, un couvert pour un seul.',
      x:['« Il continuait d’acheter deux baguettes chaque matin. »', 'La robe de mariée jaunie et les pendules arrêtées de Miss Havisham dans *Les Grandes Espérances*.'],
      s:['Montrer plutôt que dire', 'Symbole', 'Détail révélateur'] },
    { n:'Motif récurrent', a:'Leitmotiv',
      d:'Élément — image, objet, couleur, son, phrase, situation — qui revient tout au long de l’œuvre et lui donne son unité thématique.',
      u:'Choisissez deux ou trois motifs liés au thème et faites-les revenir aux moments clés, avec des variations. Le motif n’est pas encore un symbole, mais il peut le devenir par accumulation.',
      x:['La « petite phrase » de la sonate de Vinteuil chez Proust, qui accompagne l’amour de Swann.', 'Les miroirs et les doubles chez Borges.', 'Le sang et le sommeil dans *Macbeth*.', 'Les trains dans *Anna Karénine*, de la première rencontre à la fin.'],
      t:'Notez les motifs dans une Note associée aux Scènes où ils apparaissent : vous aurez la liste de toutes leurs occurrences.',
      s:['Symbole', 'Répétition et refrain', 'Champ lexical', 'Semer et récolter'] },
    { n:'Temps verbaux comme effet de style', a:'Passé simple · imparfait · passé composé · présent de narration',
      d:'Le choix des temps est une ressource de style. Le passé simple raconte les actions de premier plan, délimitées (« il entra ») ; l’imparfait peint l’arrière-plan, l’habitude et la durée (« il entrait toujours à huit heures ») ; le plus-que-parfait recule (« il était entré ») ; le passé composé rapproche le récit de la parole (*L’Étranger*) ; le présent de narration rend l’action immédiate (« il entre, regarde autour de lui »).',
      u:'Alternez passé simple et imparfait comme la figure et le fond. Passer au présent dans un moment d’intensité, au sein d’un récit au passé, produit un effet de gros plan. Les règles de conjugaison et de concordance sont dans la section Grammaire.',
      c:'Pour une longue analepse, posez le plus-que-parfait à l’entrée et à la sortie, et revenez au passé simple au milieu. Évitez de mélanger passé simple et passé composé sans raison dans la même narration.',
      x:['« Il pleuvait. L’homme attendait sous l’auvent. Soudain, il traversa la rue. »', 'L’« éternel imparfait » de Flaubert, que Proust admirait et qui donne au temps la couleur de l’ennui.', 'Le passé composé de Camus dans *L’Étranger*, qui juxtapose les faits sans les lier.'],
      s:['Temps de la narration', 'Analepse', 'Scène et sommaire'] },
    { n:'Intertextualité', a:'Allusion · citation · épigraphe · réécriture',
      d:'Dialogue d’un texte avec d’autres : citations, allusions, réécritures, épigraphes, personnages et titres empruntés. Gérard Genette en a fait la typologie dans *Palimpsestes* (1982).',
      u:'Ajoute des couches de sens pour qui reconnaît la référence — sans exclure qui ne la reconnaît pas. L’épigraphe donne la clé de lecture ; le titre peut déjà être une citation.',
      x:['*Vendredi ou les Limbes du Pacifique* (Michel Tournier) réécrit *Robinson Crusoé* du point de vue de Vendredi.', '*Meursault, contre-enquête* (Kamel Daoud) répond à *L’Étranger* en donnant un nom à l’Arabe tué.', '*Ulysse* (Joyce) réécrit l’*Odyssée* en une journée à Dublin.', '*La Prisonnière des Sargasses* (Jean Rhys) raconte la « folle du grenier » de *Jane Eyre*.'],
      s:['Pastiche et parodie', 'Métafiction'] },
    { n:'Pastiche et parodie', d:'Pastiche : imitation du style d’un auteur, d’un genre ou d’une époque, par hommage ou par exercice. Parodie : imitation à visée comique ou critique.',
      u:'Utiles pour les documents à l’intérieur du roman (lettres, journaux, rapports), pour le roman historique et pour la satire. Bien imiter un style est aussi la meilleure façon de l’apprendre.',
      x:['Proust, *Pastiches et mélanges* : l’affaire Lemoine racontée à la manière de Balzac, de Flaubert, de Saint-Simon.', '*À la manière de…* (Paul Reboux et Charles Muller), recueils de pastiches célèbres.', '*Don Quichotte* parodie les romans de chevalerie ; *Le Nom de la rose* (Umberto Eco) pastiche la chronique médiévale.'],
      s:['Intertextualité', 'Comique et humour', 'Récit épistolaire ou documentaire'] },
    { n:'Comique et humour', a:'Comique de mots, de situation, de caractère, de gestes, de mœurs',
      d:'Les grands ressorts du rire selon la tradition française héritée de Molière : comique de mots (jeux de mots, registres décalés, erreurs de langage), de situation (quiproquos, coïncidences, renversements), de caractère (un personnage dominé par une manie ou un défaut), de gestes (coups, chutes, mimiques) et de mœurs (la satire d’un milieu). Bergson y voyait « du mécanique plaqué sur du vivant » (*Le Rire*).',
      u:'Le rire naît du décalage : entre ce qu’on attend et ce qui arrive, entre le ton et le sujet, entre ce que le personnage pense de lui et ce que le lecteur voit. Une respiration comique avant ou après une scène dure renforce les deux.',
      c:'Expliquer la plaisanterie la tue ; les personnages qui rient de leurs propres mots aussi.',
      x:['« Castigat ridendo mores » (il corrige les mœurs en riant), devise associée à la comédie de Molière.', 'Le quiproquo de la cassette dans *L’Avare* : Harpagon parle de son argent, Valère de sa fille.', 'Le portier ivre juste après le meurtre dans *Macbeth*.', 'Voltaire, Courteline, Marcel Aymé, Pratchett, Wodehouse.'],
      s:['Ironie', 'Jeu de mots', 'Ton', 'Rythme ternaire'] },
    { n:'Impressionnisme littéraire', a:'Écriture artiste (Goncourt)',
      d:'Au lieu de décrire l’objet, on note la sensation qu’il produit à l’instant où il est perçu : d’abord la tache de couleur, l’éclat, le son — ensuite seulement (ou jamais) la chose. Pratiqué par les Goncourt (qui parlaient d’« écriture artiste »), par Flaubert, Zola et Daudet, puis par Proust.',
      u:'Placez la qualité avant la chose (« une blancheur de jupe » au lieu d’« une jupe blanche »), employez des noms abstraits de qualité au pluriel (« des blancheurs », « des luisances »), des tournures impersonnelles, des phrases nominales, la synesthésie et l’hypallage. Restituez la perception telle qu’elle arrive : idéal pour la focalisation interne, la pénombre, le mouvement, la distance.',
      c:'Systématique, le procédé devient précieux et vague : la chose finit par disparaître.',
      x:['« Une blancheur de jupe bougea dans l’ombre. »', 'Les Goncourt, *Germinie Lacerteux* et leur *Journal*.', 'Les clochers de Martinville chez Proust, qui changent de place selon la route.'],
      s:['Hypallage', 'Synesthésie', 'Adjectif expressif', 'Couleur et lumière', 'Focalisation'] },
    { n:'Portrait', a:'Prosopographie (physique) · éthopée (moral)',
      d:'Description d’un personnage. La rhétorique classique distingue la prosopographie, portrait physique, et l’éthopée, portrait du caractère et des mœurs ; ensemble, elles forment le portrait complet. Les « caractères » de La Bruyère en ont fait un genre.',
      u:'Le portrait réaliste en bloc, à l’entrée du personnage, a laissé place au portrait dispersé : un trait maintenant, un autre plus tard, toujours lié à une action. Faites suggérer le moral par le physique, et passez le portrait par le regard de celui qui voit — l’amoureux ne voit pas ce que voit le créancier. La caricature choisit un seul trait et l’exagère.',
      c:'Gare au cliché du personnage qui se décrit devant son miroir.',
      x:['Les *Caractères* de La Bruyère : Giton le riche, Phédon le pauvre, en deux portraits symétriques.', 'Le père Grandet de Balzac, dont chaque trait physique dit l’avarice.', 'Darcy vu par Elizabeth, avant et après Pemberley (*Orgueil et Préjugés*).'],
      s:['Détail révélateur', 'Description', 'Caricature et grotesque', 'Caractérisation directe et indirecte'] },
    { n:'Hypotypose', a:'Description vive · évidence',
      d:'Description si animée et si détaillée d’une scène ou d’une action que le lecteur a l’impression de l’avoir sous les yeux. C’est le « mettre sous les yeux » de la rhétorique classique.',
      u:'Présent de narration, verbes de mouvement, détails sensoriels en succession rapide, phrases qui suivent le rythme de ce qu’on voit. Réservez-la aux moments que le lecteur doit garder comme une image : la bataille, la tempête, l’incendie, l’entrée triomphale.',
      x:['Le récit de Théramène dans *Phèdre* (Racine) : le monstre surgi des flots et la mort d’Hippolyte.', 'Waterloo vu par Fabrice dans *La Chartreuse de Parme* (Stendhal), et par Hugo dans *Les Misérables*.', 'La descente dans la mine au début de *Germinal*.'],
      s:['Images sensorielles', 'Description', 'Montrer plutôt que dire', 'Temps verbaux comme effet de style', 'Style cinématographique'] },
    { n:'Ekphrasis', a:'Description d’œuvre d’art',
      d:'Description littéraire d’une œuvre d’art visuelle — tableau, statue, bouclier, tapisserie, photographie —, réelle ou inventée.',
      u:'L’œuvre décrite sert de miroir à l’histoire : elle résume le thème, annonce la suite, révèle celui qui la regarde. Décrivez ce que le personnage y voit, et non ce qui s’y trouve. La photo de famille est l’ekphrasis la plus courante du roman contemporain.',
      x:['Le bouclier d’Achille au chant XVIII de l’*Iliade* — l’exemple fondateur.', 'La *Vue de Delft* de Vermeer et son « petit pan de mur jaune », devant lequel meurt Bergotte chez Proust.', '*Le Chef-d’œuvre inconnu* (Balzac) : un tableau que personne ne peut voir.', '*Le Portrait de Dorian Gray* (Oscar Wilde) : le tableau qui vieillit.'],
      s:['Mise en abyme', 'Symbole', 'Description', 'Intertextualité'] },
    { n:'Couleur et lumière', a:'Chromatisme · clair-obscur',
      d:'L’usage délibéré des couleurs et de l’éclairage dans la description : une palette dominante, une couleur qui revient, des contrastes d’ombre et de lumière.',
      u:'Donnez à chaque lieu ou personnage une palette, et à l’histoire une couleur qui accumule du sens. Soyez précis : pas « bleu », mais « bleu de chauffe ». La lumière (heure, saison, lampe, néon) décide de l’atmosphère plus que les objets.',
      c:'Les associations usées (rouge-passion, noir-mort) fonctionnent mieux contredites.',
      x:['Le rouge et le noir de Stendhal, titre devenu énigme.', 'Le jaune de la *Vue de Delft* chez Proust ; le blanc de *L’Aveuglement* (Saramago).', 'Le rouge des servantes dans *La Servante écarlate* (Margaret Atwood).'],
      s:['Motif récurrent', 'Symbole', 'Impressionnisme littéraire', 'Atmosphère'] },
    { n:'Contraste et juxtaposition', a:'Montage',
      d:'Placer côte à côte, sans commentaire, deux images, scènes, tons ou personnages qui s’éclairent par leur différence.',
      u:'C’est le montage du cinéma appliqué à la prose : le sens naît de la coupe. Un banquet suivi d’une scène de famine se passe de tout discours. Cela fonctionne à l’échelle de la phrase, du paragraphe et du chapitre.',
      x:['*Madame Bovary*, les comices agricoles : les serments de Rodolphe entrecoupés de l’annonce des prix pour les fumiers.', 'Dans *Germinal*, le déjeuner des Grégoire juste avant la misère des Maheu.', 'Le baptême et les exécutions dans *Le Parrain*.'],
      s:['Antithèse', 'Montage alterné', 'Ironie', 'Faire-valoir'] },
    { n:'Caricature et grotesque', d:'Caricature : portrait qui exagère un ou deux traits jusqu’au ridicule. Grotesque : mélange du comique et du difforme, du monstrueux ou du répugnant, qui fait rire et dérange à la fois. Hugo en a fait un principe esthétique dans la *Préface de Cromwell* (1827).',
      u:'La caricature est l’arme de la satire : elle fixe un personnage secondaire une fois pour toutes. Le grotesque montre un monde détraqué — le corps qui trahit, l’autorité ridicule, l’horreur quotidienne.',
      c:'Un personnage principal caricaturé en permanence perd son humanité, et le lecteur s’en désintéresse.',
      x:['Quasimodo dans *Notre-Dame de Paris* ; Ubu dans *Ubu roi* (Jarry).', 'Rabelais ; Gogol (*Le Nez*) ; Dickens.', 'Les caricatures de Daumier, version dessinée de Monsieur Prudhomme et de Robert Macaire.'],
      s:['Hyperbole', 'Comique et humour', 'Satire', 'Portrait', 'Personnage type'] }
  ]},
  { name:'Tons et esthétiques', items:[
    { n:'Registres littéraires', a:'Comique, tragique, pathétique, lyrique, épique, fantastique, satirique, polémique, didactique',
      d:'Notion centrale de l’enseignement français : le registre (ou tonalité) est l’effet dominant qu’un texte cherche à produire sur le lecteur. Comique : faire rire. Tragique : montrer l’homme écrasé par une fatalité. Pathétique : émouvoir, faire pitié. Lyrique : exprimer les sentiments personnels. Épique : magnifier des exploits collectifs. Fantastique : instiller le doute entre naturel et surnaturel. Satirique et polémique : attaquer. Didactique : enseigner.',
      u:'Un roman mêle les registres ; décidez lequel domine chaque Scène et ménagez les passages de l’un à l’autre. Les grands effets naissent souvent des ruptures : une scène pathétique désamorcée par un détail comique, un épisode comique qui bascule dans le tragique.',
      c:'Ne pas confondre avec les registres de langue (soutenu, courant, familier). Et un registre affiché n’est pas un registre atteint : écrire « c’était terrible » ne rend pas une scène tragique.',
      x:['Épique : la bataille de Waterloo dans *Les Misérables*.', 'Fantastique : *Le Horla* (Maupassant) — folie ou présence invisible ?', 'Tragique : *Thérèse Raquin* (Zola) ; pathétique : la mort de Fantine.', 'Mélange : *Cyrano de Bergerac*, du comique de la tirade du nez au pathétique de la mort de Cyrano.'],
      s:['Ton', 'Registres de langue', 'Pathétique et sentimentalisme', 'Satire', 'Fantastique'] },
    { n:'Satire', d:'Critique des vices, des mœurs, des institutions ou des personnes par le ridicule. Ce n’est pas un genre, c’est une intention : elle peut prendre la forme d’un roman, d’une pièce, d’un poème, d’un conte philosophique ou d’une chronique.',
      u:'Exagérez d’un cran seulement au-delà du réel, gardez la logique interne et l’air sérieux. La satire a besoin d’une cible nette et, sous le rire, d’indignation.',
      c:'Elle date quand la cible disparaît ; et le sermon guette toujours.',
      x:['Molière ; les *Satires* de Boileau ; *Les Caractères* de La Bruyère.', '*Candide* (Voltaire) ; *Lettres persanes* (Montesquieu) : Paris vu par deux Persans.', '*Les Voyages de Gulliver* et *Modeste proposition* (Swift) ; *La Ferme des animaux* (Orwell).'],
      s:['Ironie', 'Caricature et grotesque', 'Comique et humour', 'Allégorie', 'Pastiche et parodie', 'Conte philosophique'] },
    { n:'Humour noir', d:'Traiter avec légèreté ou drôlerie ce qui est tragique, macabre ou tabou — la mort, la maladie, la guerre, la cruauté. André Breton lui a consacré une *Anthologie de l’humour noir* (1940).',
      u:'L’effet vient du ton impassible : plus le sujet est grave, plus la voix est calme. Il permet de regarder l’insupportable en face et caractérise ceux qui en vivent près — soldats, médecins, croque-morts.',
      c:'Rire des victimes n’est pas rire avec elles : la cible doit être l’absurde, le pouvoir ou le narrateur lui-même.',
      x:['*Modeste proposition* (Swift) : résoudre la famine en Irlande en mangeant les enfants.', '*Candide* : les malheurs les plus atroces racontés d’un ton enjoué.', 'Alphonse Allais ; *Abattoir 5* (Vonnegut) ; *Catch-22* (Heller).'],
      s:['Ton', 'Ironie', 'Dysphémisme', 'Litote', 'Absurde'] },
    { n:'Pathétique et sentimentalisme', a:'Pathos · mélodrame · bathos',
      d:'Le pathétique est l’appel à la pitié et à l’émotion du lecteur (le « pathos » de la rhétorique). Il devient sentimentalisme quand l’émotion demandée dépasse ce que la scène justifie ; et il tombe dans le « bathos » — mot d’Alexander Pope — quand, voulant le sublime, il bascule dans le ridicule.',
      u:'L’émotion forte demande de la retenue : plus le personnage pleure, moins le lecteur pleure. Montrez le petit geste et laissez la larme au lecteur. Le bathos volontaire, à l’inverse, est un ressort comique.',
      x:['Retenu : « Elle plia son pull et le rangea, comme tous les jeudis. »', 'Sentimental : « Son pauvre cœur brisé saignait d’une douleur infinie. »', 'Flaubert se moque du romanesque sentimental à travers les lectures d’Emma Bovary.', 'Bathos comique : « Ô Mort, ô Destin, ô Sécurité sociale ! »'],
      s:['Corrélatif objectif', 'Montrer plutôt que dire', 'Gradation', 'Litote', 'Registres littéraires'] },
    { n:'Baroque, préciosité et burlesque', a:'Esthétiques du XVIIe siècle',
      d:'Trois esthétiques du premier XVIIe siècle français, avant le classicisme. Le baroque aime le mouvement, l’instabilité, l’illusion, les métamorphoses, l’accumulation d’images (Théophile de Viau, Saint-Amant, l’*Illusion comique* de Corneille). La préciosité raffine le langage et les sentiments : périphrases, analyse amoureuse, la Carte de Tendre de Madeleine de Scudéry. Le burlesque traite un sujet noble en style bas (Scarron, *Le Virgile travesti*), tandis que l’héroï-comique fait l’inverse.',
      u:'Le baroque enseigne le vertige et le trompe-l’œil (théâtre dans le théâtre, songes, masques) ; la préciosité, l’analyse fine des sentiments et l’art de la conversation ; le burlesque, le décalage comique entre sujet et style. Utile pour des voix de narrateur, des pastiches d’époque ou des scènes de salon.',
      c:'La préciosité a donné son contraire : les *Précieuses ridicules* de Molière. Imité sans distance, le style précieux devient grotesque.',
      x:['*L’Illusion comique* (Corneille) : une pièce où le spectateur découvre qu’il regardait des comédiens.', 'La Carte de Tendre, dans *Clélie* (Madeleine de Scudéry).', '*Le Roman comique* (Scarron) : des comédiens ambulants racontés en style burlesque.'],
      s:['Périphrase', 'Antithèse', 'Hyperbole', 'Mise en abyme', 'Pastiche et parodie'] },
    { n:'Réalisme et naturalisme', d:'L’esthétique de la seconde moitié du XIXe siècle : observer la société contemporaine avec exactitude, sans idéaliser. Le naturalisme pousse le programme plus loin et explique les personnages par l’hérédité et le milieu, comme dans une expérience scientifique (Zola, *Le Roman expérimental*, 1880).',
      u:'Comme style : description minutieuse des milieux (la maison explique ceux qui l’habitent), narrateur impersonnel, détail documentaire, discours indirect libre, ironie. C’est encore la langue par défaut du roman.',
      c:'L’inventaire exhaustif lasse ; le déterminisme ôte aux personnages leur liberté — et leur intérêt.',
      x:['*Le Père Goriot* et *Eugénie Grandet* (Balzac), précurseurs.', '*Madame Bovary* (Flaubert) ; *Bel-Ami* (Maupassant).', '*Les Rougon-Macquart* (Zola) : *L’Assommoir*, *Germinal*.'],
      s:['Description', 'Détail révélateur', 'Discours indirect libre', 'Vraisemblance', 'Roman de mœurs'] },
    { n:'Style oral (skaz)', a:'Récit parlé · oralité écrite',
      d:'Narration écrite comme si elle était dite à voix haute par quelqu’un qui n’est pas écrivain : syntaxe de la parole, hésitations, répétitions, apartés, vocabulaire populaire. La critique russe l’a appelée « skaz ».',
      u:'Donne une voix inimitable et une grande proximité. Imaginez à qui parle le narrateur, où, et pourquoi maintenant. L’oralité se construit : c’est une illusion faite de rythme et de quelques marques (« ça » pour « cela », dislocations, chute du « ne »), pas une transcription.',
      c:'Difficile à tenir sur un long livre sans lasser ; et à traduire.',
      x:['*Voyage au bout de la nuit* (Céline) : la langue parlée entrée en littérature en 1932.', '*Zazie dans le métro* (Queneau) ; *La Vie devant soi* (Émile Ajar).', 'Gogol (*Le Manteau*) ; *Les Aventures de Huckleberry Finn* (Mark Twain).'],
      s:['Voix narrative', 'Idiolecte et marques d’oralité', 'Anacoluthe', 'Discours direct libre', 'Auteur, narrateur et narrataire'] },
    { n:'Style noir (hard-boiled)', a:'Polar dur à cuire',
      d:'La prose du roman noir américain des années 1920-1940, importée en France par la « Série noire » de Gallimard (1945) : narrateur cynique, souvent à la première personne, phrases sèches, dialogue tranchant, comparaisons inattendues, ville la nuit.',
      u:'Trois ingrédients : observation froide des détails, humour de quelqu’un qui a tout vu, et de temps en temps une comparaison qui surprend. Le sentiment existe, mais il n’est jamais avoué.',
      c:'Trop imité, il devient sa propre parodie.',
      x:['Dashiell Hammett (*Le Faucon de Malte*) et Raymond Chandler (*Le Grand Sommeil*).', 'Léo Malet et Nestor Burma ; Jean-Patrick Manchette (*Le Petit Bleu de la côte Ouest*).', 'À la manière de Chandler : « Il passait aussi inaperçu qu’une tarentule sur une part de gâteau. »'],
      s:['Phrase courte', 'Comparaison', 'Ton', 'Théorie de l’iceberg', 'Première personne — protagoniste', 'Roman policier'] },
    { n:'Gothique', a:'Roman noir (au sens du XVIIIe siècle) · frénétique',
      d:'Esthétique de la peur et de l’excès, née en Angleterre au XVIIIe siècle et appelée alors « roman noir » en France : demeures anciennes et isolées, secrets de famille, passé qui revient, surnaturel (ou son soupçon), nature menaçante.',
      u:'L’essentiel est l’atmosphère : le lieu agit comme un personnage et comme une image de l’esprit de ceux qui l’habitent. Suggérez plus que vous ne montrez ; le doute — y a-t-il un fantôme ? — fait plus peur que la certitude.',
      x:['*Le Château d’Otrante* (Horace Walpole), le fondateur.', '*Frankenstein* ; *Dracula* ; *Les Hauts de Hurlevent*.', 'En France : *Le Diable amoureux* (Cazotte), les contes de Nodier, *Les Diaboliques* (Barbey d’Aurevilly).', '*Rebecca* (Daphne du Maurier), gothique moderne.'],
      s:['Atmosphère', 'Paysage état d’âme', 'Ambiguïté', 'Fantastique', 'Suspense et surprise'] },
    { n:'Absurde', d:'Représentation d’un monde sans logique ni sens, où les personnages persistent à agir comme s’il en avait un. La narration traite l’insensé avec un sérieux total. Camus en a fait une philosophie (*Le Mythe de Sisyphe*, 1942).',
      u:'Acceptez une prémisse impossible et développez-la avec une rigueur bureaucratique. Le comique et l’angoisse naissent de la même source : la disproportion entre le calme du ton et l’énormité de ce qui se passe.',
      x:['*Le Procès* et *Le Château* (Kafka).', '*En attendant Godot* (Beckett) ; *La Cantatrice chauve* et *Rhinocéros* (Ionesco).', '*L’Étranger* (Camus) ; *Le Passe-muraille* (Marcel Aymé), absurde souriant.'],
      s:['Ton', 'Humour noir', 'Vraisemblance', 'Réalisme magique', 'Défamiliarisation'] },
    { n:'Maximalisme', d:'Le contraire du minimalisme : abondance assumée — phrases longues, digressions, énumérations, érudition, foule de personnages et de fils, désir de faire entrer le monde entier dans le livre.',
      u:'Il exige une énergie de phrase et une architecture solide sous l’excès. Il fonctionne quand l’abondance est le sujet : une ville, une époque, un esprit qui ne se tait pas.',
      c:'Sans maîtrise, ce n’est qu’un manque de coupes.',
      x:['*Gargantua* et *Pantagruel* (Rabelais) ; *Tristram Shandy* (Sterne).', '*La Vie mode d’emploi* (Perec) ; *Les Bienveillantes* (Jonathan Littell).', '*Ulysse* (Joyce) ; *L’Infinie Comédie* (David Foster Wallace), avec ses centaines de notes.'],
      s:['Phrase longue', 'Énumération', 'Pause descriptive', 'Phrase courte', 'Récit en mosaïque', 'Minimalisme'] }
  ]},
  { name:'Ouverture, fin et page', items:[
    { n:'Incipit', a:'Première phrase · ouverture',
      d:'Les premiers mots du livre. Ils établissent la voix, le ton et le pacte de lecture, et doivent soulever une question qui oblige à lire la phrase suivante.',
      u:'On peut ouvrir par une voix, une anomalie, une maxime, un lieu, une mort annoncée, un dialogue. Pas besoin d’être spectaculaire, mais il faut être exact quant au livre promis. C’est souvent la dernière phrase écrite.',
      c:'Ouvertures usées : le réveil qui sonne, le rêve, le bulletin météo, le personnage devant son miroir.',
      x:['« Longtemps, je me suis couché de bonne heure » (Proust, *Du côté de chez Swann*).', '« Aujourd’hui, maman est morte » (Camus, *L’Étranger*).', '« Ça a débuté comme ça » (Céline, *Voyage au bout de la nuit*).', '« Comment s’étaient-ils rencontrés ? Par hasard, comme tout le monde » (Diderot, *Jacques le Fataliste*).'],
      s:['In medias res', 'Voix narrative', 'Ton', 'Excipit', 'Accroche et cliffhanger'] },
    { n:'Excipit', a:'Dernière phrase · clausule finale',
      d:'Les derniers mots du livre : ceux qui restent dans l’oreille et décident de l’impression finale.',
      u:'Terminez sur une image, un geste ou une réplique plutôt que sur une explication. Un écho de l’incipit ou d’un motif referme le cercle. Le rythme compte autant que le sens : lisez-le à voix haute.',
      x:['« À nous deux maintenant ! » (Balzac, *Le Père Goriot*) : Rastignac défie Paris.', '« Il vient de recevoir la croix d’honneur » (Flaubert, *Madame Bovary*) : le triomphe de Homais, ironie finale.', '« C’est là ce que nous avons eu de meilleur ! » (Flaubert, *L’Éducation sentimentale*).', '*Gatsby le Magnifique* : les barques à contre-courant, ramenées sans cesse vers le passé.'],
      s:['Incipit', 'Dénouement', 'Place forte de la phrase', 'Motif récurrent', 'Récit circulaire'] },
    { n:'Titre', d:'Le premier texte que lit le lecteur. Il peut nommer le héros, le lieu, un objet ou une image centrale, le thème, ou citer un autre texte.',
      u:'Un bon titre intrigue avant la lecture et prend un second sens après. Testez-le : se dit-il bien à voix haute ? Se distingue-t-il sur une table de libraire ? Les titres de chapitres sont une ressource à part : ils promettent, résument avec ironie (« Où l’on voit… » à la manière du XVIIIe siècle) ou égarent.',
      x:['Le nom du héros : *Madame Bovary*, *Eugénie Grandet*, *Le Père Goriot*.', 'L’énigme : *Le Rouge et le Noir* ; *À la recherche du temps perdu*.', 'Le titre qui raconte la fin : *Chronique d’une mort annoncée* (García Márquez).', 'L’absent : *En attendant Godot* ; *Rebecca*.'],
      s:['Intertextualité', 'Incipit', 'Symbole', 'Chapitres courts et cliffhangers'] },
    { n:'Procédés typographiques', a:'Mise en page · notes · italique',
      d:'L’usage expressif de l’aspect visuel du texte : italiques, majuscules, polices, notes de bas de page, pages blanches, disposition des lignes, images et documents reproduits.',
      u:'L’italique sert à l’insistance, aux pensées, aux mots étrangers et aux titres ; les majuscules, aux cris et aux enseignes. Les notes de bas de page créent une seconde voix — érudite, comique ou contradictoire. Lettres, messages et coupures de presse gagnent à avoir leur propre aspect.',
      c:'L’effet graphique ne remplace pas la phrase ; il peut se perdre en édition numérique ou en livre audio.',
      x:['*Tristram Shandy* (Sterne) : une page toute noire pour la mort de Yorick.', 'Les *Calligrammes* d’Apollinaire ; *Un coup de dés jamais n’abolira le hasard* (Mallarmé), poème éclaté sur la double page.', 'Terry Pratchett : la Mort parle en PETITES CAPITALES ; les notes de bas de page sont des plaisanteries.'],
      s:['Ponctuation et effets de style', 'Paragraphe et blanc typographique', 'Récit épistolaire ou documentaire', 'Métafiction'] }
  ]}
]});
